let state;try{state=JSON.parse(localStorage.getItem('centring-lantern-workspace-v1'))}catch{}if(!state||!state.report||!state.readiness||!state.tasks)state=defaults();
let selectedDate=pacificDate(),month=Number(selectedDate.slice(5,7))-1,year=Number(selectedDate.slice(0,4)),filter='all',oppFilter='all',query='',mobileOpen=false,toastTimer;
