const federal=createGrantBrowser({workspaceSaved:()=>opportunities.filter(o=>state.saved.includes(o.id)).map(oppRow),navigate:r=>go(r),esc,heading,showDialog,closeDialog,render,getSaved:()=>Array.isArray(state.federalGrants)?state.federalGrants:[],save:items=>savePersonalState({...state,federalGrants:items}),toast,getDocumentId:id=>studioDocuments.find(d=>d.importedGrantId===String(id))?.id,openDocument:id=>{studioTab='insights';go('studio/'+id);},importGrant:async grant=>{const doc=await saveGrantNotice(grant,null);closeDialog();studioFilter='favorites';studioSearch='';go('library');toast('Grant notice saved in Documents.');return doc;},startDraft:grant=>startOpportunityDraft(grant),ask:prompt=>{chatDraft=prompt;chatOpen=true;refreshChat();$('#beedy-message')?.focus();},calendar:date=>{selectedDate=date;year=Number(date.slice(0,4));month=Number(date.slice(5,7))-1;go('calendar');}});
const dateLabel=(date,opts={day:'numeric',month:'short'})=>new Date(date+'T12:00:00').toLocaleDateString('en-GB',opts);
const iso=(y,m,d)=>`${y}-${String(m+1).padStart(2,'0')}-${String(d).padStart(2,'0')}`;
function pacificDate(now=new Date()){
 const parts=new Intl.DateTimeFormat('en-US',{timeZone:'America/Los_Angeles',year:'numeric',month:'2-digit',day:'2-digit'}).formatToParts(now);
 const part=type=>parts.find(p=>p.type===type).value;
 return `${part('year')}-${part('month')}-${part('day')}`;
}
function weekStart(day=pacificDate()){const d=new Date(day+'T12:00:00');return plusDays(day,-((d.getDay()+6)%7));}
function currentDateHeading(){return heading('Your next steps',`<span class="date">${dateLabel(pacificDate(),{weekday:'long',day:'numeric',month:'long'})} · Pacific time</span>`);}
function selectToday(){selectedDate=pacificDate();year=Number(selectedDate.slice(0,4));month=Number(selectedDate.slice(5,7))-1;}
const route=()=>location.hash.slice(1)||'today';
const go=r=>{if(route()===r)render();else location.hash=r;};
function toast(text){$('#toast').textContent=text;$('#toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),3300)}
function navLink(href,label,ic){let current=route().split('/')[0];if(current==='connections')current='plugins';if(current==='studio')current='library';return `<a href="#${href}" class="${current===href||(href==='today'&&['calendar','timeline','readiness'].includes(current))?'active':''}" ${current===href?'aria-current="page"':''}>${icon(ic)}${label}</a>`}
function renderBase(){const r=route();document.title=`${r.startsWith('discussions')?'Team discussion':r==='settings'?'Your profile':r==='connections'||r==='plugins'?'Plugins':r.startsWith('studio')?'Grant studio':r==='library'?'Your documents':r.startsWith('opportunities')?'Opportunities':r.startsWith('reports')?'Awards & reports':r==='calendar'?'Calendar':r==='readiness'?'Readiness':r.startsWith('applications')?'Applications':r.startsWith('tasks')?'Team tasks':r==='timeline'?'Timeline':'Your next steps'} · Centring`;$('#app').innerHTML=`<aside class="sidebar ${mobileOpen?'open':''}" aria-label="Main navigation"><a class="brand" href="#today">Centring</a><nav class="nav">${navLink('today','Today','today')}${navLink('opportunities','Opportunities','search')}${navLink('applications','Applications','file')}${navLink('tasks','Team tasks','today')}${navLink('discussions','Team discussion','discussion')}${navLink('reports','Awards & reports','layers')}</nav><nav class="nav secondary">${navLink('library','Documents','book')}${navLink('plugins','Plugins','layers')}${navLink('settings','Settings','settings')}</nav><div class="sidebar-foot"><nav class="nav"><a href="#help">${icon('help')}Help & next steps</a></nav><a class="person person-link" href="#settings">${personAvatar()}<span><strong>${esc(state.name)}</strong><small>${esc(state.profileRole||'Programme lead')}</small></span></a></div></aside><header class="topbar"><button class="iconbtn mobile-toggle" data-action="menu" aria-label="${mobileOpen?'Close':'Open'} navigation" aria-expanded="${mobileOpen}">${icon(mobileOpen?'close':'menu')}</button><span class="org">${esc(state.org)} <small class="preview-tag">Preview</small></span><div class="topright"><button class="cloud-status" data-action="cloud-settings" title="Shared workspace storage">${esc(cloudMessage)}</button><button class="btn beedy-launch" aria-label="Ask Beedy" data-action="chat-toggle" aria-expanded="${chatOpen}"><img src="assets/beedy-cutout.png" alt="">Ask Beedy</button>${notificationBell()}<details class="account-menu"><summary aria-label="Open account menu">${personAvatar()}<span aria-hidden="true">⌄</span></summary><nav aria-label="Account menu"><span>${esc(state.name)}</span><a href="#settings">Your profile</a><a href="#discussions">Team discussion</a><a href="#plugins">Plugins</a><button type="button" class="textlink" data-demo-signout ${agentConnection==='ready'&&agentSignInMethod==='demo'?'':'hidden'}>Sign out</button></nav></details></div></header><div class="shell"><main id="main" tabindex="-1"><div data-guidance-slot>${guidancePanel(r)}</div>${page(r)}</main><footer class="footer">${r==='library'||r.startsWith('studio/')?'Documents · Shared workspace':r==='opportunities'?'Live federal listings · Shared workspace':'Centring · Your grant workspace'}</footer></div>`;}
function heading(title,sub=''){return `<div class="page-heading"><h1>${title}</h1>${sub}</div>`}
function todayTabs(active){return `<nav class="tabs" aria-label="Today views">${[['today','Overview'],['calendar','Calendar'],['timeline','Timeline'],['readiness','Readiness']].map(([id,label])=>`<a href="#${id}" class="${active===id?'active':''}" ${active===id?'aria-current="page"':''}>${label}</a>`).join('')}</nav>`}
function page(r){if(r.startsWith('studio/'))return documentWorkspace(r.split('/')[1]);if(r==='plugins')return pluginsPage();if(r==='discussions'||r.startsWith('discussions/'))return discussionsPage(r.split('/')[1]);if(r==='tasks')return tasksPage();if(r.startsWith('tasks/'))return taskPage(r.split('/')[1]);if(r==='timeline')return timelinePage();if(r==='today')return overview();if(r==='calendar')return calendar();if(r==='readiness')return readinessPage();if(['opportunities','opportunities/saved','opportunities/workspace'].includes(r))return oppPage();if(r==='applications')return applications();if(r.startsWith('applications/'))return application(r.split('/')[1]);if(r==='reports')return reports();if(['reports/community-arts','reports/community-arts/edit'].includes(r))return report();if(r==='library')return documentLibrary();if(r==='settings')return personalSettings();if(r==='connections')return pluginsPage();if(r==='help')return help();return heading('Page not found')+'<a href="#today" class="btn">Back to today</a>'}
function oppRow(o){return `<button class="opprow" data-action="opportunity" data-id="${o.id}"><span><strong>${o.name}</strong><span class="sub">${o.funder}${state.saved.includes(o.id)?' · Saved':''}</span></span><span class="fit">${o.fit}<span class="sub">${o.eligibility}</span></span><span class="money"><strong>${o.amount}</strong><span class="sub">Closes ${dateLabel(o.deadline)}</span></span><span class="arrow">›</span></button>`}
function overviewBase(){return currentDateHeading()+todayTabs('today')+`<section class="priority"><div><h2>${state.report.sentOn?'Closeout recorded':'Review the award closeout'}</h2><p>Welcoming Spaces · ${closeoutStatus()}</p><p>${state.report.sentOn?'Your team has recorded when it sent the report to the funder.':'Check what the grant paid for and record when your team sends the report.'}</p></div><a class="btn primary" href="#reports/community-arts">${state.report.sentOn?'View record':'Review closeout'}</a></section><section class="section"><div class="sectionhead"><h2>New opportunities</h2><a class="textlink" href="#opportunities/workspace">View all</a></div>${opportunities.slice(0,2).map(oppRow).join('')}</section><section class="section"><div class="sectionhead"><h2>The next seven days</h2><a class="textlink" href="#calendar">Full calendar</a></div><div class="week">${Array.from({length:7},(_,i)=>{const d=plusDays(pacificDate(),i);const ev=events().filter(e=>e.date===d&&!e.done);return `<button class="weekday" data-action="day" data-date="${d}" aria-label="${dateLabel(d,{weekday:'long',day:'numeric',month:'long'})}${ev.length?': '+ev.map(e=>esc(e.title)).join(', '):', no tasks'}"><span class="dayname">${dateLabel(d,{weekday:'short'})}</span><span class="daynum ${i===0?'todaynum':''}">${Number(d.slice(8))}</span><div class="weeknote">${ev.map(e=>esc(e.title)).join('<br>')}</div></button>`}).join('')}</div></section>`}
function sampleOppPage(){return heading('Opportunities')+'<p class="intro">Review these opportunities and confirm eligibility before applying.</p>'+`<div class="toolbar"><div class="search">${icon('search')}<input type="search" id="opp-search" aria-label="Search opportunities" placeholder="Search by name, funder, or focus" value="${esc(query)}"></div><div class="pilltabs" aria-label="Opportunity filter"><button data-action="opp-filter" data-id="all" class="${oppFilter==='all'?'active':''}" aria-pressed="${oppFilter==='all'}">All opportunities</button><button data-action="opp-filter" data-id="saved" class="${oppFilter==='saved'?'active':''}" aria-pressed="${oppFilter==='saved'}">Saved (${state.saved.length})</button></div></div><div id="opp-results">${oppResults()}</div><p class="note">These are fictional opportunities for exploring the dashboard. Live funding listings are available in the Live opportunities tab.</p>`}
function oppPage(){return federal.page()+(federal.isDemo()?sampleOppPage():'');}
function oppResults(){const rows=opportunities.filter(o=>(oppFilter==='all'||state.saved.includes(o.id))&&`${o.name} ${o.funder} ${o.area}`.toLowerCase().includes(query.toLowerCase()));return rows.length?rows.map(oppRow).join(''):`<div class="empty"><h3>${query?'No matching opportunities':'Your shortlist starts here'}</h3><p>${query?'Try a different name or focus.':'Open an opportunity and save it for later.'}</p></div>`}
function opportunity(id){if(id?.startsWith('federal-')){void federal.open(id.slice(8));return;}const o=opportunities.find(x=>x.id===id);if(!o)return;showDialog(`<h2 id="dialog-title">${o.name}</h2>`,`<p class="muted">${o.funder} · ${o.area}</p><p>${o.description}</p><div class="facts"><div><small>Funding range</small><strong>${o.amount}</strong></div><div><small>Application deadline</small><strong>${dateLabel(o.deadline,{day:'numeric',month:'long',year:'numeric'})}</strong></div></div><h3>Why it may fit</h3><p>${o.reason}</p><h3>Before you apply</h3><p>${o.check}</p><p class="small muted">${o.term}</p><p class="inline-message">${state.saved.includes(id)?'Saved to your shortlist. The deadline is on your calendar.':'Save this opportunity to add its deadline to your calendar.'}</p><div class="dialog-actions"><button class="btn primary" data-action="start-application" data-id="${id}">Open application</button><button class="btn" data-action="save-opportunity" data-id="${id}">${state.saved.includes(id)?'Remove from saved':'Save opportunity'}</button>${state.saved.includes(id)?'<button class="textlink" data-action="open-shortlist">View saved opportunities</button>':''}</div><p class="note">Example opportunity. Submit applications through the funder’s portal.</p>`)}
function calendar(){const first=new Date(year,month,1);const offset=(first.getDay()+6)%7;const start=new Date(year,month,1-offset);const all=events().filter(e=>filter==='all'||e.type===filter);return heading('Your next steps')+todayTabs('calendar')+`<div class="month-heading"><div><h2>${first.toLocaleDateString('en-GB',{month:'long',year:'numeric'})}</h2><p class="calendar-zone">Today is ${dateLabel(pacificDate(),{day:'numeric',month:'long'})} · Pacific time</p></div><div class="controls"><button class="btn" data-action="prev-month" aria-label="Previous month">‹</button><button class="btn" data-action="this-month">Today</button><button class="btn" data-action="next-month" aria-label="Next month">›</button><button class="btn primary" data-action="add-task">Add a task</button></div></div><div class="toolbar"><label for="event-filter" class="small muted">Show</label><select id="event-filter"><option value="all" ${filter==='all'?'selected':''}>All events</option><option value="task" ${filter==='task'?'selected':''}>Team tasks</option><option value="report" ${filter==='report'?'selected':''}>Report deadlines</option><option value="opportunity" ${filter==='opportunity'?'selected':''}>Grant deadlines</option><option value="funding" ${filter==='funding'?'selected':''}>Funding dates</option><option value="decision" ${filter==='decision'?'selected':''}>Decisions & follow-ups</option></select><span class="small muted">Hover or select a day to see its events.</span></div><div class="calendar"><div class="calendar-labels">${['Mon','Tue','Wed','Thu','Fri','Sat','Sun'].map(d=>`<div>${d}</div>`).join('')}</div><div class="calendar-grid">${Array.from({length:Math.ceil((offset+new Date(year,month+1,0).getDate())/7)*7},(_,i)=>{const d=new Date(start);d.setDate(start.getDate()+i);const key=iso(d.getFullYear(),d.getMonth(),d.getDate());const ev=all.filter(e=>e.date===key);return `<button class="calday ${d.getMonth()!==month?'outside':''} ${key===selectedDate?'selected':''}" data-action="select-date" data-date="${key}" ${key===pacificDate()?'aria-current="date"':''} aria-pressed="${key===selectedDate}" aria-label="${dateLabel(key,{day:'numeric',month:'long'})}, ${ev.length} events"><span class="daynum ${key===pacificDate()?'todaynum':''}">${d.getDate()}</span>${ev.slice(0,2).map(e=>`<span class="cal-event ${e.done?'done':''}">${esc(e.title)}</span>`).join('')}${ev.length>2?`<span class="small">+${ev.length-2} more</span>`:''}</button>`}).join('')}</div></div><section class="agenda"><div class="sectionhead"><h2>${dateLabel(selectedDate,{weekday:'long',day:'numeric',month:'long'})}</h2><button class="textlink" data-action="add-task">Add task for this day</button></div>${all.filter(e=>e.date===selectedDate).map(eventRow).join('')||'<p class="muted small">No events scheduled.</p>'}</section>`}
function readinessPage(){const complete=readiness.filter(r=>state.readiness[r.id]).length;const next=readiness.find(r=>!state.readiness[r.id]);return heading('Your next steps')+todayTabs('readiness')+`<div class="readiness-top"><h2>${next?'Prepare your application':'Preparation checklist complete'}</h2><p class="intro">${next?`Next up: ${next.title.toLowerCase()}. Check each item when your team has it ready.`:'You have the basics ready. Each funder may still ask for something specific.'}</p><span class="small muted">${complete} of ${readiness.length} essentials ready</span><div class="progress" role="progressbar" aria-valuenow="${complete}" aria-valuemin="0" aria-valuemax="6" aria-label="Readiness essentials"><span style="width:${complete/6*100}%"></span></div></div>${readiness.map(r=>`<div class="checkrow"><input type="checkbox" id="ready-${r.id}" data-ready="${r.id}" ${state.readiness[r.id]?'checked':''}><label for="ready-${r.id}"><strong>${r.title}</strong><p>${r.id==='reviewer'?esc(state.name)+' will review the application before submission.':r.description}</p></label><span class="status">${state.readiness[r.id]?'Ready':'To prepare'}</span></div>`).join('')}<p class="note">This is your team’s checklist, not an eligibility decision. Ticking an item doesn’t upload or verify a document.</p><div class="report-actions"><a href="#opportunities" class="btn ${complete===6?'primary':''}">Explore opportunities</a><a href="#library" class="textlink">View preparation templates</a></div>`}
function reportsBase(){return heading('Awards & reports')+`<p class="intro">Track awards, spending, and reporting deadlines.</p><div class="simple-row" style="margin-top:25px"><div class="row-main"><h3>Welcoming Spaces</h3><p class="small muted">Neighbourhood Futures · ${money(state.report.awarded)} awarded</p></div><span class="status">${closeoutStatus()}</span><a class="btn primary" href="#reports/community-arts">${state.report.sentOn?'View record':'Review closeout'}</a></div>`}
function report(){
 const r=state.report, path='#reports/community-arts';
 const editing=route()==='reports/community-arts/edit'&&!r.sentOn;
 const ready=Boolean(r.summary?.trim()&&r.impact?.trim()&&Number.isFinite(r.spent));
 const status=r.sentOn?'Sent':r.approved?'Reviewed':'Awaiting review';
 const header=`<a class="textlink back" href="#reports">← Awards &amp; reports</a>${heading('Welcoming Spaces')}<p class="intro">Award closeout · Neighbourhood Futures</p>`;
 const body=editing?`<form id="report-form" class="closeout-card"><h2>Edit report</h2><label class="field">Work completed<textarea name="summary" rows="3" required>${esc(r.summary)}</textarea></label><label class="field">Outcome<textarea name="impact" rows="3" required>${esc(r.impact)}</textarea></label><label class="field">Expenditure ($)<input name="spent" type="number" min="0" max="${r.awarded}" step="0.01" required value="${esc(r.spent)}"></label><div class="dialog-actions"><button class="btn primary" name="action" value="save">Save changes</button><a class="btn" href="${path}">Cancel</a></div></form>`:
 `<article class="closeout-card"><div class="sectionhead"><h2>Report summary</h2>${r.sentOn?'':`<a class="textlink" href="${path}/edit">Edit report</a>`}</div><h3>Work completed</h3><p>${esc(r.summary)||'Add the work completed.'}</p><h3>Outcome</h3><p>${esc(r.impact)||'Add the outcome for participants.'}</p><div class="closeout-finance"><div><small>Award</small><strong>${money(r.awarded)}</strong></div><div><small>Spent</small><strong>${money(r.spent)}</strong></div><div><small>Balance</small><strong>${money(r.awarded-r.spent)}</strong></div></div></article>`;
 return header+`<div class="closeout-layout">${body}<aside class="closeout-card closeout-review"><h2>Report review</h2><dl><dt>Status</dt><dd>${status}</dd><dt>Due</dt><dd>${dateLabel(closeoutDue())}</dd><dt>Reviewer</dt><dd>${esc(state.name)}</dd></dl>${editing?'':r.sentOn?`<p>Sent on ${dateLabel(r.sentOn)}.</p>`:r.approved?`<form id="report-sent-form"><label class="field">Date sent to funder<input type="date" name="sentOn" required max="${pacificDate()}" value="${pacificDate()}"></label><button class="btn primary">Record submission</button></form>`:ready?'<button class="btn primary" data-action="review-closeout">Mark reviewed</button>':`<a class="btn primary" href="${path}/edit">Complete report</a>`}${editing?'':'<button class="textlink" data-action="export-closeout">Export record</button>'}<a class="textlink" href="#applications/spaces">View award application</a></aside></div>`;
}
function money(n){return Number(n).toLocaleString('en-US',{style:'currency',currency:'USD',maximumFractionDigits:2})}
function library(){return heading('Library')+'<p class="intro">Simple starting points for your team. Download a template and make it your own.</p>'+[['brief','Programme brief','Outline your idea, people, activities, and intended impact.'],['budget','Budget worksheet','List your costs, contributions, and funding request.'],['closeout','Closeout checklist','Gather the outcomes and figures for your final report.']].map(([id,title,desc])=>`<div class="simple-row"><div class="row-main"><h3>${title}</h3><p class="small muted">${desc}</p></div><button class="btn" data-action="template" data-id="${id}">Download</button></div>`).join('')+'<p class="note">Templates are text or CSV files. No organisation documents have been uploaded.</p>'}
function legacySettings(){return heading('Settings')+`<div class="settings"><form id="settings-form"><label class="field">Organisation name<input name="org" value="${esc(state.org)}" required maxlength="80"></label><label class="field">Reviewer name<input name="name" value="${esc(state.name)}" required maxlength="60"></label><button class="btn primary">Save details</button></form><section><h3>Workspace settings</h3><p class="muted small">Workspace changes sync to the cloud. Example records are included. Submit applications through the funder’s portal.</p><button class="btn danger" data-action="reset">Reset workspace</button></section></div>`}
function help(){return heading('Help & next steps')+`<p class="intro">Find grants, manage applications, and review documents. Your work syncs to your signed-in workspace.</p><div class="simple-row"><div class="row-main"><h3>Find something that fits</h3><p class="small muted">Open a grant, check the fit, and save it. Its deadline will appear in Calendar.</p></div><a class="btn" href="#opportunities">Opportunities</a></div><div class="simple-row"><div class="row-main"><h3>Get your essentials ready</h3><p class="small muted">Work through a practical six-item checklist before starting a proposal.</p></div><a class="btn" href="#readiness">Readiness</a></div><div class="simple-row"><div class="row-main"><h3>Review a report</h3><p class="small muted">Record what the award delivered, how much was spent, and when your team sent the report.</p></div><a class="btn" href="#reports/community-arts">Review report</a></div>`}
let priorFocus;
// A reminder remains outstanding until its work is completed or it is explicitly addressed.
function notificationKey(event){return JSON.stringify([event.type,event.id,event.date,event.title]);}
function notificationItems(today=new Date()){
 const until=plusDays(pacificDate(today),7);
 const addressed=state.addressedNotifications||{};
 return events().filter(e=>!e.done&&e.status!=='done'&&e.date<=until).map(e=>({...e,key:notificationKey(e),addressed:!!addressed[notificationKey(e)]}));
}
function setNotificationAddressed(key,value,today=new Date()){
 if(!notificationItems(today).some(e=>e.key===key))return false;
 const addressed={...state.addressedNotifications};
 if(value)addressed[key]=true;else delete addressed[key];
 return savePersonalState({...state,addressedNotifications:addressed});
}
function notificationBell(){
 const count=notificationItems().filter(e=>!e.addressed).length;
 return `<button class="iconbtn notification-bell" data-action="notifications" aria-label="Notifications, ${count} outstanding" title="${count} outstanding notifications">${icon('bell')}<span class="notification-count ${count?'':'is-empty'}" aria-hidden="true">${count>99?'99+':count}</span></button>`;
}
function refreshNotificationBell(){const bell=document.querySelector('.notification-bell');if(bell){const restoreFocus=priorFocus===bell;bell.outerHTML=notificationBell();if(restoreFocus)priorFocus=document.querySelector('.notification-bell');}}
function showNotifications(tab='pending'){
 const items=notificationItems(),pending=items.filter(e=>!e.addressed),addressed=items.filter(e=>e.addressed),shown=tab==='addressed'?addressed:pending;
 showDialog('<h2 id="dialog-title">Notifications</h2>',`<div class="notification-centre"><p class="muted small">Overdue items and dates in the next seven days.</p><div class="pilltabs notification-tabs"><button data-action="notification-tab" data-id="pending" aria-pressed="${tab==='pending'}" class="${tab==='pending'?'active':''}">Outstanding <span>${pending.length}</span></button><button data-action="notification-tab" data-id="addressed" aria-pressed="${tab==='addressed'}" class="${tab==='addressed'?'active':''}">Addressed <span>${addressed.length}</span></button></div><div class="notification-list">${shown.length?shown.map(e=>`<article class="notification-item"><div class="notification-symbol">${icon(e.type==='task'?'today':e.type==='report'?'file':'bell')}</div><div class="notification-content"><h3>${esc(e.title)}</h3><p>${dateLabel(e.date,{day:'numeric',month:'long',year:'numeric'})}</p><div class="notification-actions"><button class="textlink" data-action="reminder-day" data-date="${esc(e.date)}" aria-label="View ${esc(e.title)}">View in calendar</button><button class="btn" data-action="${e.addressed?'notification-restore':'notification-address'}" data-key="${esc(e.key)}" aria-label="${e.addressed?'Restore':'Mark addressed:'} ${esc(e.title)}">${e.addressed?'Restore':'Mark addressed'}</button></div></div></article>`).join(''):`<div class="notification-empty">${icon('bell')}<h3>${tab==='addressed'?'No addressed notifications':'You’re all caught up'}</h3><p>${tab==='addressed'?'Items you mark addressed will appear here.':'New reminders will appear as dates approach.'}</p></div>`}</div><p class="notification-footnote">Addressing a reminder clears it from the bell. It doesn’t complete the task or change its deadline.</p></div>`);
 document.querySelector(`.notification-tabs [data-id="${tab}"]`)?.focus();
}
function showDialog(title,body){const d=$('#detail');if(!d.open)priorFocus=document.activeElement;d.innerHTML=`<div class="dialoghead">${title}<button class="iconbtn close" data-action="close-dialog" aria-label="Close dialog">${icon('close')}</button></div>${body}`;if(!d.open)d.showModal();}
function closeDialog(){$('#detail').close();priorFocus?.isConnected&&priorFocus.focus()}
function download(name,text,type='text/plain'){const a=document.createElement('a'),url=URL.createObjectURL(new Blob([text],{type}));a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),500);toast('Download ready')}
document.addEventListener('click',e=>{if(e.target.closest('.skip')){e.preventDefault();$('#main').focus();return}const b=e.target.closest('[data-action]');if(!b)return;const id=b.dataset.id;switch(b.dataset.action){case'export-closeout':{const r=state.report;download('Welcoming-Spaces-closeout.txt',`WELCOMING SPACES CLOSEOUT RECORD\nSample data\n\nOrganisation: ${state.org}\nReviewer: ${state.name}\nStatus: ${closeoutStatus()}\nDue: ${dateLabel(closeoutDue())}\n\nWHAT WE DELIVERED\n${r.summary}\n\nTHE DIFFERENCE IT MADE\n${r.impact}\n\nAward: ${money(r.awarded)}\nSpent: ${money(r.spent)}\nRemaining: ${money(r.awarded-r.spent)}\n\nReport sent: ${r.sentOn||'Not recorded'}\n`);break;}case'review-closeout':if(!state.report.sentOn&&savePersonalState({...state,report:{...state.report,approved:true,checked:true}})){render();toast('Report reviewed');}break;case'menu':mobileOpen=!mobileOpen;render();break;case'close-dialog':closeDialog();break;case'opportunity':opportunity(id);break;case'open-shortlist':closeDialog();go('opportunities/saved');break;case'save-opportunity':{const adding=!state.saved.includes(id);if(savePersonalState({...state,saved:adding?[...state.saved,id]:state.saved.filter(x=>x!==id)})){render();opportunity(id);toast(adding?'Saved to Opportunities':'Removed from saved opportunities');}break;}case'start-application':if(!state.applications[id]){state.applications[id]=newApplication(id);if(!state.saved.includes(id))state.saved.push(id);persist()}closeDialog();go('applications/'+id);break;case'opp-filter':oppFilter=id;render();break;case'day':selectedDate=b.dataset.date;year=Number(selectedDate.slice(0,4));month=Number(selectedDate.slice(5,7))-1;go('calendar');break;case'select-date':selectedDate=b.dataset.date;render();document.querySelector('.agenda')?.scrollIntoView({block:'nearest',behavior:'auto'});break;case'prev-month':month--;if(month<0){month=11;year--}selectedDate=iso(year,month,1);render();break;case'next-month':month++;if(month>11){month=0;year++}selectedDate=iso(year,month,1);render();break;case'this-month':selectToday();render();break;case'add-task':addTask();break;case'toggle-task':{const t=state.tasks.find(t=>t.id===id);if(t){t.done=!t.done;t.status=t.done?'done':'todo';t.checks=(t.checks||[]).map(c=>({...c,done:t.done}));persist();render()}break;}case'delete-task':showDialog('<h2 id="dialog-title">Remove this task?</h2>',`<p>This removes it from your calendar.</p><div class="dialog-actions"><button class="btn" data-action="close-dialog">Keep task</button><button class="btn danger" data-action="confirm-delete-task" data-id="${id}">Remove task</button></div>`);break;case'confirm-delete-task':state.tasks=state.tasks.filter(t=>t.id!==id);persist();closeDialog();render();toast('Task removed');break;case'open-report':closeDialog();go('reports/community-arts');break;case'notifications':showNotifications();break;case'notification-tab':showNotifications(b.dataset.id);break;case'notification-address':if(setNotificationAddressed(b.dataset.key,true)){refreshNotificationBell();showNotifications();}break;case'notification-restore':if(setNotificationAddressed(b.dataset.key,false)){refreshNotificationBell();showNotifications('addressed');}break;case'reminder-day':closeDialog();selectedDate=b.dataset.date;year=Number(selectedDate.slice(0,4));month=Number(selectedDate.slice(5,7))-1;go('calendar');break;case'template':if(id==='budget')download('Centring-budget-template.csv','Item,Quantity,Unit cost,Total cost,Notes\nTeaching artists,,,,\nMaterials,,,,\nVenue,,,,\nAccessibility support,,,,\nOther contributions,,,,','text/csv');else download('Centring-'+id+'-template.txt',id==='brief'?'PROGRAMME BRIEF\n\nProgramme name:\n\nPeople and place:\n\nWhat will you do?\n\nWhat difference will it make?\n\nActivities and timeline:\n\nFunding requested:\n\nTeam reviewer:\n':'CLOSEOUT CHECKLIST\n\n[ ] Confirm delivered activities\n[ ] Gather participant feedback\n[ ] Reconcile spending against budget\n[ ] Check remaining funds with the funder\n[ ] Review supporting evidence\n[ ] Get final team approval\n[ ] Submit through the funder portal\n[ ] Keep a copy of the confirmation\n');break;case'reset':showDialog('<h2 id="dialog-title">Start fresh?</h2>','<p>This clears your saved opportunities, application drafts, tasks, discussions, and checklist changes. Uploaded documents and their drafts are kept in your document library.</p><div class="dialog-actions"><button class="btn" data-action="close-dialog">Keep my changes</button><button class="btn danger" data-action="confirm-reset">Reset workspace</button></div>');break;case'confirm-reset':state=defaults();migrateDemo();persist();closeDialog();go('today');toast('Workspace reset');break;}});
document.addEventListener('input',e=>{if(e.target.id==='opp-search'){query=e.target.value;$('#opp-results').innerHTML=oppResults()}if(e.target.name==='spent'&&$('#balance'))$('#balance').textContent=money(state.report.awarded-Number(e.target.value));});
document.addEventListener('change',e=>{if(e.target.dataset.ready){state.readiness[e.target.dataset.ready]=e.target.checked;persist();const id=e.target.id;render();document.getElementById(id)?.focus();}if(e.target.id==='event-filter'){filter=e.target.value;render()}});
document.addEventListener('submit',e=>{e.preventDefault();const f=e.target,d=new FormData(f);if(f.id==='task-form'){const title=String(d.get('title')).trim();if(!title){f.elements.title.setCustomValidity('Give your task a name.');f.elements.title.reportValidity();f.elements.title.oninput=()=>f.elements.title.setCustomValidity('');return}state.tasks.push({id:crypto.randomUUID(),title,date:String(d.get('date')),type:'task',done:false});selectedDate=String(d.get('date'));year=Number(selectedDate.slice(0,4));month=Number(selectedDate.slice(5,7))-1;persist();closeDialog();render();toast('Task added to your calendar')}if(f.id==='application-form-legacy'){const id=f.dataset.id;state.applications[id]={title:String(d.get('title')).trim(),description:String(d.get('description')).trim(),amount:Number(d.get('amount')),status:e.submitter?.value==='review'?'review':'draft'};persist();render();toast(e.submitter?.value==='review'?'Draft ready for your team to review':'Draft saved')}if(f.id==='report-sent-form'){
 const sentOn=String(d.get('sentOn')||'');
 if(!state.report.approved||state.report.sentOn||!/^\d{4}-\d{2}-\d{2}$/.test(sentOn)||sentOn>pacificDate())return;
 state.report.sentOn=sentOn;persist();render();toast('Report submission recorded');return;
}if(f.id==='report-form'){if(state.report.sentOn)return;const summary=String(d.get('summary')).trim(),impact=String(d.get('impact')).trim(),spent=Number(d.get('spent'));if(!summary||!impact){toast('Add the work completed and its outcome.');return;}const changed=summary!==state.report.summary||impact!==state.report.impact||spent!==state.report.spent;if(changed&&!savePersonalState({...state,report:{...state.report,summary,impact,spent,approved:false,checked:false}}))return;go('reports/community-arts');toast('Report saved');}if(f.id==='settings-form'){state.org=String(d.get('org')).trim()||defaults().org;state.name=String(d.get('name')).trim()||defaults().name;persist();render();toast('Details saved')}});
window.addEventListener('hashchange',()=>{mobileOpen=false;if($('#detail').open)closeDialog();render();window.scrollTo(0,0);$('#main').focus({preventScroll:true})});
$('#detail').addEventListener('click',e=>{if(e.target===$('#detail')){const b=e.target.getBoundingClientRect();if(e.clientX<b.left||e.clientX>b.right||e.clientY<b.top||e.clientY>b.bottom)closeDialog()}});

// Connected demo workspace: real UI state, sample records, no external submissions.
const members=[{id:'sarah',name:()=>state.name,role:'Programme lead'},{id:'alex',name:()=> 'Alex Rivera',role:'Finance'},{id:'jordan',name:()=> 'Jordan Ellis',role:'Community programmes'}];
const prepSteps=['Programme brief','Budget checked','Eligibility confirmed','Supporting documents','Final team review'];
const stages={draft:'Draft in progress',review:'Ready for review',submitted:'Submitted',awarded:'Award confirmed',received:'Funding received',declined:'Not awarded'};
const taskStates={todo:'To do',doing:'In progress',done:'Complete'};
let chatExpanded=false,chatOpen=false,taskOwner='all',taskFilter='active',appFilter='all',timelineStart=weekStart(),chatDraft='',taskEditId=null;
const ownerName=id=>members.find(m=>m.id===id)?.name()||'Unassigned';
function newApplication(id){return {title:'Open Studio Saturdays',description:'Free weekend art workshops for young people in our neighbourhood.',amount:15000,status:'draft',owner:'sarah',start:pacificDate(),deadline:opportunities.find(o=>o.id===id)?.deadline||sampleDate(21),checks:prepSteps.map((name,i)=>({name,done:i===0})),history:[]};}
function migrateDemo(){
 if(state.version!==2){
  const seeds={creative:{...newApplication('creative'),checks:prepSteps.map((name,i)=>({name,done:i<3}))},heritage:{...newApplication('heritage'),title:'Neighbourhood Stories',round:'Community round',deadline:sampleDate(-3),start:sampleDate(-21),amount:30000,status:'submitted',submitted:sampleDate(-3),reference:'LCF-2026-041',decisionDate:sampleDate(25),followup:sampleDate(11),acknowledged:true,checks:prepSteps.map(name=>({name,done:true})),history:[{label:'Submission recorded',date:sampleDate(-3)},{label:'Receipt confirmed by funder',date:sampleDate(-2)}]},spaces:{...newApplication('spaces'),title:'A More Welcoming Studio',round:'Community round',deadline:sampleDate(-10),start:sampleDate(-28),amount:12000,status:'awarded',owner:'alex',submitted:sampleDate(-12),reference:'NF-2026-118',decisionDate:sampleDate(-4),fundingDate:sampleDate(11),acknowledged:true,checks:prepSteps.map(name=>({name,done:true})),history:[{label:'Submission recorded',date:sampleDate(-12)},{label:'Award confirmed',date:sampleDate(-4)}]}};
  state.applications={...seeds,...state.applications};
  for(const [id,a] of Object.entries(state.applications)){state.applications[id]={...newApplication(id),...a,checks:a.checks||prepSteps.map((name,i)=>({name,done:a.status==='review'||i<2})),history:a.history||[]};}
  state.tasks=state.tasks.map(t=>({...t,owner:'sarah',start:sampleDate(0),status:t.done?'done':'todo',related:t.id==='team'?'creative':'',notes:'',checks:[{name:'Complete the review',done:!!t.done}]}));
  state.tasks.push({id:'budget',title:'Check the workshop budget',owner:'alex',start:sampleDate(0),date:sampleDate(3),status:'doing',done:false,type:'task',related:'creative',notes:'Confirm artist fees and accessibility costs before Sarah gives the final OK.',checks:[{name:'Check artist fees',done:true},{name:'Confirm venue costs',done:true},{name:'Review accessibility costs',done:false}]},{id:'funding-setup',title:'Prepare for the funding arrival',owner:'alex',start:sampleDate(7),date:sampleDate(11),status:'todo',done:false,type:'task',related:'spaces',notes:'Check the award agreement and confirm the expected payment with the funder. Record the receipt only after funds land.',checks:[{name:'Check the signed agreement',done:false},{name:'Confirm the payment date',done:false},{name:'Set up a project budget code',done:false}]},{id:'venue',title:'Confirm accessible venue dates',owner:'jordan',start:sampleDate(1),date:sampleDate(9),status:'todo',done:false,type:'task',related:'spaces',notes:'Hold the next workshop dates with the community centre.',checks:[{name:'Check availability',done:false},{name:'Confirm access arrangements',done:false}]});
  state.version=2;state.chat=[];
 }
 state.chat=state.chat||[];
 if(!Array.isArray(state.discussions))state.discussions=seedDiscussions(pacificDate());
 state.discussionDrafts=state.discussionDrafts||{};
}
migrateDemo();persist();
function mountDocumentVoice(){const d=studioDoc();if(!d)return;const target=document.querySelector('.studio-tabs')||document.querySelector('[aria-label="Document views"]');target?.append(voiceButton(()=>{const edits=d.review?.edits||[];if(!edits.length)return null;return {kind:'edits',total:edits.length,edits:edits.slice(0,12).map(e=>({status:e.status||'suggested',before:String(e.before||'').slice(0,500),after:String(e.after||e.suggested||'').slice(0,500),reason:String(e.reason||'').slice(0,300)}))};}));}

function render(){hideDayPreview();syncBeedyDocument();stopSourceViewer();renderBase();document.querySelectorAll('[data-organisation-banner]').forEach(blendOrganisationBanner);federal.mount();if(route().startsWith('studio/'))mountDocumentVoice();document.body.classList.toggle('chat-open',chatOpen);document.body.classList.toggle('chat-expanded',chatOpen&&chatExpanded);$('#app').insertAdjacentHTML('beforeend',chatPanel());if(route().startsWith('studio/')&&shouldMountSourceViewer(studioDoc(),studioTab,sourceMode))mountSourceViewer(studioDoc(),studioTab==='review'?{review:true,mode:reviewMode,onSelect:selectReviewSuggestion}:{});}
function daysBetween(a,b){return Math.round((new Date(b+'T12:00:00')-new Date(a+'T12:00:00'))/86400000)}
function plusDays(d,n){const date=new Date(d+'T12:00:00');date.setDate(date.getDate()+n);return iso(date.getFullYear(),date.getMonth(),date.getDate())}
function taskProgress(t){return t.done?100:t.checks?.length?Math.round(t.checks.filter(c=>c.done).length/t.checks.length*100):0}
function applicationProgress(a){if(['submitted','awarded','received','declined'].includes(a.status))return {value:a.status==='received'||a.status==='declined'?100:a.status==='awarded'?67:a.acknowledged?33:0,label:'Follow-up milestones',detail:a.status==='declined'?'Decision recorded · Application closed':`${Number(!!a.acknowledged)+Number(['awarded','received'].includes(a.status))+Number(a.status==='received')} of 3 milestones recorded`};const n=a.checks.filter(c=>c.done).length;return {value:Math.round(n/a.checks.length*100),label:'Preparation',detail:`${n} of ${a.checks.length} steps complete`};}
function progressHTML(p){return `<div class="work-progress"><div><span>${p.label}</span><strong>${p.value}%</strong></div><div class="progress" role="progressbar" aria-label="${p.label}" aria-valuemin="0" aria-valuemax="100" aria-valuenow="${p.value}"><span style="width:${p.value}%"></span></div><small>${p.detail}</small></div>`}
function grant(id){return opportunities.find(o=>o.id===id)}
function ownerSelect(value,name='owner'){return `<select name="${name}"><option value="">Unassigned</option>${members.map(m=>`<option value="${m.id}" ${value===m.id?'selected':''}>${esc(m.name())} · ${m.role}</option>`).join('')}</select>`}
function relatedSelect(value){return `<select name="related"><option value="">General team task</option>${Object.keys(state.applications).map(id=>`<option value="${id}" ${id===value?'selected':''}>${grant(id).name}</option>`).join('')}</select>`}
function taskRow(t){return `<div class="task-row">${personAvatar(t.owner)}<a href="#tasks/${t.id}" class="row-main"><h3>${esc(t.title)}</h3><p>${esc(ownerName(t.owner))} · Due ${dateLabel(t.date)}${t.related?' · '+grant(t.related).name:''}</p></a><div class="compact-progress"><span>${taskProgress(t)}%</span><div class="progress"><span style="width:${taskProgress(t)}%"></span></div></div><span class="status">${taskStates[t.status]}</span><a href="#tasks/${t.id}" class="iconbtn" aria-label="Open task: ${esc(t.title)}">${icon('arrow')}</a></div>`}
function overviewV2(){let base=overviewBase();const active=state.tasks.filter(t=>!t.done).sort((a,b)=>a.date.localeCompare(b.date));const work=`<section class="section"><div class="sectionhead"><h2>Your team’s next steps</h2><a class="textlink" href="#tasks">All tasks</a></div>${active.slice(0,2).map(taskRow).join('')||'<p class="muted">Your team is caught up.</p>'}</section>`;return base.replace('<section class="section"><div class="sectionhead"><h2>New opportunities',work+'<section class="section"><div class="sectionhead"><h2>New opportunities');}
function tasksPage(){const visible=state.tasks.filter(t=>(taskOwner==='all'||t.owner===taskOwner)&&(taskFilter==='all'||(taskFilter==='complete'?t.done:taskFilter==='active'?!t.done:t.status===taskFilter))).sort((a,b)=>a.date.localeCompare(b.date));return heading('Team tasks','<button class="btn primary" data-action="add-task">Add a task</button>')+`<p class="intro">A clear owner, a next step, and room to get things done.</p><div class="toolbar"><label class="small" for="task-owner">Assigned to</label><select id="task-owner"><option value="all">Everyone</option>${members.map(m=>`<option value="${m.id}" ${taskOwner===m.id?'selected':''}>${esc(m.name())}</option>`).join('')}<option value="" ${taskOwner===''?'selected':''}>Unassigned</option></select><label class="small" for="task-filter">Show</label><select id="task-filter">${[['active','Open tasks'],['todo','To do'],['doing','In progress'],['complete','Completed'],['all','All tasks']].map(([v,l])=>`<option value="${v}" ${taskFilter===v?'selected':''}>${l}</option>`).join('')}</select><a href="#timeline" class="textlink toolbar-end">See timeline</a></div>${visible.map(taskRow).join('')||'<div class="empty">No tasks in this view.</div>'}`}
function taskPage(id){const t=state.tasks.find(t=>t.id===id);if(!t)return heading('Task not found')+'<a href="#tasks" class="btn">All tasks</a>';return '<a class="textlink back" href="#tasks">← Team tasks</a>'+heading(esc(t.title),`<button class="btn" data-action="chat-toggle">Ask Beedy</button>`)+`<div class="work-summary"><div><span class="small muted">${esc(ownerName(t.owner))} · Due ${dateLabel(t.date)}</span><p class="small">${t.related?`For <a class="textlink" href="#applications/${t.related}">${grant(t.related).name}</a>`:'General team task'}</p>${t.discussionId?`<a class="textlink" href="#discussions/${esc(t.discussionId)}">Back to team discussion</a>`:''}${t.documentId?`<a class="textlink" href="#studio/${esc(t.documentId)}">Open source document in Grant studio</a>`:''}</div>${progressHTML({value:taskProgress(t),label:'Task progress',detail:`${(t.checks||[]).filter(c=>c.done).length} of ${(t.checks||[]).length} steps complete`})}</div><form id="task-edit-form" data-id="${id}" class="report-sheet"><label class="field">Task name<input name="title" value="${esc(t.title)}" maxlength="120" required></label><div class="money-inputs"><label class="field">Assigned to${ownerSelect(t.owner)}</label><label class="field">Status<select name="status">${Object.entries(taskStates).map(([v,l])=>`<option value="${v}" ${t.status===v?'selected':''}>${l}</option>`).join('')}</select></label></div><div class="money-inputs"><label class="field">Start date<input type="date" name="start" value="${t.start}" required></label><label class="field">Due date<input type="date" name="date" value="${t.date}" min="${t.start}" required></label></div><label class="field">Related application${relatedSelect(t.related)}</label><label class="field">Notes<textarea name="notes">${esc(t.notes)}</textarea></label><h3>Task checklist</h3>${(t.checks||[]).map((c,i)=>`<label class="step-check"><input type="checkbox" name="step-${i}" ${c.done?'checked':''}><span>${esc(c.name)}</span></label>`).join('')}<label class="field extra-step">Add another step<input name="newstep" placeholder="Optional next step" maxlength="100"></label><div class="report-actions"><button class="btn primary" name="action" value="save">Save task</button><button class="btn" name="action" value="complete">${t.done?'Keep completed':'Mark complete'}</button></div><p class="note">Assignments are saved in this browser. Team members aren’t notified.</p></form>`}
function addTask(){taskEditId=null;showDialog('<h2 id="dialog-title">Create a task</h2>',`<form id="new-team-task"><label class="field">Task name<input name="title" maxlength="120" required placeholder="e.g. Confirm the programme budget"></label><label class="field">Assigned to${ownerSelect('sarah')}</label><div class="money-inputs"><label class="field">Start date<input name="start" type="date" value="${selectedDate}" required></label><label class="field">Due date<input name="date" type="date" value="${selectedDate}" min="${selectedDate}" required></label></div><label class="field">Related application${relatedSelect(route().startsWith('applications/')?route().split('/')[1]:'')}</label><label class="field">Notes<textarea name="notes" style="min-height:80px"></textarea></label><button class="btn primary">Create task</button></form>`)}
function applications(){const ids=Object.keys(state.applications).filter(id=>appFilter==='all'||(appFilter==='active'?['draft','review'].includes(state.applications[id].status):appFilter==='waiting'?state.applications[id].status==='submitted':appFilter==='awards'?['awarded','received'].includes(state.applications[id].status):['submitted','awarded','received','declined'].includes(state.applications[id].status)));return heading('Applications','<a class="btn" href="#opportunities">Find an opportunity</a>')+`<p class="intro">See what’s taking shape, what’s submitted, and what comes next.</p><div class="toolbar"><div class="pilltabs">${[['all','All'],['active','In preparation'],['waiting','Awaiting decision'],['awards','Awards'],['submitted','Submitted & decisions']].map(([v,l])=>`<button data-action="application-filter" data-id="${v}" class="${appFilter===v?'active':''}" aria-pressed="${appFilter===v}">${l}</button>`).join('')}</div></div>${ids.map(id=>{const a=state.applications[id],o=grant(id),p=applicationProgress(a);return `<a class="application-row" href="#applications/${id}"><div><span class="status">${stages[a.status]}</span><h3>${o.name}</h3><p class="small muted">${esc(a.title)} · ${esc(ownerName(a.owner))}</p><p class="small muted">${['draft','review'].includes(a.status)?'Apply by '+dateLabel(a.deadline):a.status==='awarded'?'Funding expected '+dateLabel(a.fundingDate):a.status==='received'?'Funding received '+dateLabel(a.receivedDate):a.status==='declined'?'Decision recorded':'Submitted '+dateLabel(a.submitted)+' · Decision expected '+dateLabel(a.decisionDate)}</p></div>${progressHTML(p)}<span class="arrow">›</span></a>`}).join('')||'<div class="empty">No applications in this view.</div>'}<p class="note">Percentages count completed preparation steps or recorded follow-up milestones. They don’t estimate the chance of winning a grant.</p>`}
function application(id){const o=grant(id),a=state.applications[id];if(!o||!a)return heading('Application not found');const live=['draft','review'].includes(a.status);return '<a class="textlink back" href="#applications">← All applications</a>'+heading(o.name,'<button class="btn" data-action="chat-toggle">Ask Beedy</button>')+`<p class="muted">${o.funder}${a.round?' · '+a.round:''}</p>${applicationPhoto(id)}<div class="work-summary"><div><span class="status">${stages[a.status]}</span><h3>${esc(a.title)}</h3><p class="small muted">${esc(ownerName(a.owner))} · ${live?'Apply by':'Application deadline'} ${dateLabel(a.deadline)} · ${money(a.amount)}</p></div>${progressHTML(applicationProgress(a))}</div>${live?applicationEditor(id,a):submissionTracking(id,a)}<section class="section linked-work"><div class="sectionhead"><h2>Related team tasks</h2><button class="textlink" data-action="add-task">Add a task</button></div>${state.tasks.filter(t=>t.related===id).map(taskRow).join('')||'<p class="muted small">No tasks yet. Give the next step an owner.</p>'}</section>`}
function applicationEditor(id,a){return `<form id="working-application" data-id="${id}" class="report-sheet"><label class="field">Programme name<input name="title" value="${esc(a.title)}" required maxlength="150"></label><label class="field">What will your programme do?<textarea name="description" required>${esc(a.description)}</textarea></label><div class="money-inputs"><label class="field">Funding requested ($)<input name="amount" type="number" min="1" max="1000000" value="${a.amount}" required></label><label class="field">Application owner${ownerSelect(a.owner)}</label></div><h3>Preparation checklist</h3>${a.checks.map((c,i)=>`<label class="step-check"><input name="prep-${i}" type="checkbox" ${c.done?'checked':''}><span>${c.name}</span></label>`).join('')}<div class="report-actions"><button class="btn primary" name="action" value="save">Save progress</button><button class="btn" name="action" value="review">Ask for review</button></div></form><div class="submission-note"><h3>Already submitted through the funder?</h3><p class="small muted">Record the submission here to track your receipt, decision, and funding.</p><button class="btn" data-action="record-submission" data-id="${id}">Record a submission</button></div>`}
function submissionTracking(id,a){const p=applicationProgress(a);return `<div class="report-sheet"><div class="milestones">${[['Receipt confirmed',a.acknowledged],['Decision recorded',['awarded','received','declined'].includes(a.status)],['Funding received',a.status==='received']].map(([l,done])=>`<div><span class="circle ${done?'complete':''}">${done?'✓':''}</span><span>${l}${a.status==='declined'&&l==='Funding received'?' · Not applicable':''}</span></div>`).join('')}</div><div class="reportmeta"><div><span>Submitted</span>${dateLabel(a.submitted)}</div><div><span>Reference</span>${esc(a.reference||'Not recorded')}</div><div><span>${a.status==='submitted'?'Expected decision':'Decision recorded'}</span>${a.decisionDate?dateLabel(a.decisionDate):'Not recorded'}</div>${a.status==='awarded'||a.status==='received'?`<div><span>${a.status==='received'?'Received':'Expected funding'}</span>${dateLabel(a.status==='received'?a.receivedDate:a.fundingDate)}</div>`:''}</div><form id="tracking-form" data-id="${id}"><label class="field">Owner${ownerSelect(a.owner)}</label><div class="money-inputs"><label class="field">${a.status==='submitted'?'Expected decision date':'Decision date'}<input name="decisionDate" type="date" value="${a.decisionDate||''}" required min="${a.submitted}" ${a.status!=='submitted'?'readonly':''}></label><label class="field">Next follow-up date<input name="followup" type="date" value="${a.followup||''}" min="${a.submitted}"></label></div>${a.status==='awarded'?`<label class="field">Expected funding date<input type="date" name="fundingDate" value="${a.fundingDate}" min="${a.submitted}" required></label>`:''}<label class="step-check"><input type="checkbox" name="acknowledged" ${a.acknowledged?'checked':''} ${a.status!=='submitted'?'disabled':''}><span>We have confirmation that the funder received our application.</span></label><label class="field extra-step">Follow-up notes<textarea name="trackingNotes">${esc(a.trackingNotes||'')}</textarea></label><button class="btn" type="submit">Save tracking details</button></form><div class="report-actions">${a.status==='submitted'?`<button class="btn primary" data-action="record-decision" data-id="${id}">Record a decision</button>`:a.status==='awarded'?`<button class="btn primary" data-action="record-funding" data-id="${id}">Record funding received</button>`:''}</div><p class="note">Expected dates are planning estimates. Updating this tracker doesn’t contact the funder or move money.</p><h3 style="margin-top:30px">Activity</h3><div class="activity">${[...(a.history||[])].reverse().map(h=>`<p><span>${dateLabel(h.date)}</span>${esc(h.label)}</p>`).join('')}</div></div>`}
function events(){const list=[...federal.events(),{id:'report',title:'Final report due',date:closeoutDue(),type:'report',done:!!state.report.sentOn},...state.tasks];for(const o of opportunities){const a=state.applications[o.id];if(a){list.push({id:o.id,title:o.name,date:a.deadline,type:'opportunity',done:!['draft','review'].includes(a.status),application:true});if(['submitted','awarded'].includes(a.status)){if(a.followup)list.push({id:o.id,title:'Follow up: '+o.name,date:a.followup,type:'decision',application:true});if(a.status==='submitted'&&a.decisionDate)list.push({id:o.id,title:'Expected decision: '+o.name,date:a.decisionDate,type:'decision',application:true})}if(['awarded','received'].includes(a.status))list.push({id:o.id,title:(a.status==='received'?'Received: ':'Funding expected: ')+o.name,date:a.status==='received'?a.receivedDate:a.fundingDate,type:'funding',done:a.status==='received',application:true})}else if(state.saved.includes(o.id))list.push({id:o.id,title:o.name,date:o.deadline,type:'opportunity',done:false});}return list.filter(e=>e.date).sort((a,b)=>a.date.localeCompare(b.date))}
function eventRow(e){return `<div class="simple-row"><span class="circle ${e.done?'complete':''}">${e.done?'✓':''}</span><div class="row-main"><h3>${esc(e.title)}</h3><p class="small muted">${e.type==='task'?esc(ownerName(e.owner))+' · '+taskStates[e.status]:e.type==='funding'?(e.done?'Funds recorded as received':'Expected date · Not yet received'):e.type==='decision'?'Planning date':e.type==='report'?'Report deadline':e.forecast?'Forecast date · Not confirmed':'Application deadline'}</p></div>${e.type==='task'?`<a class="btn" href="#tasks/${e.id}">Open task</a>`:e.application?`<a class="btn" href="#applications/${e.id}">Open application</a>`:`<button class="btn" data-action="${e.type==='report'?'open-report':'opportunity'}" data-id="${e.id}">Open ${e.type==='report'?'report':'opportunity'}</button>`}</div>`}
function reports(){const awards=Object.entries(state.applications).filter(([id,a])=>['awarded','received'].includes(a.status));return reportsBase()+`<section class="section"><h2>Funding on its way</h2>${awards.map(([id,a])=>`<div class="simple-row"><div class="row-main"><h3>${grant(id).name}</h3><p class="small muted">${money(a.amount)} · ${a.status==='received'?'Received '+dateLabel(a.receivedDate):'Expected '+dateLabel(a.fundingDate)} · ${esc(ownerName(a.owner))}</p></div><a class="btn" href="#applications/${id}">Open award</a></div>`).join('')||'<p class="muted">No awards recorded yet.</p>'}</section>`}
function timelinePage(){const end=plusDays(timelineStart,41);const rows=[...Object.entries(state.applications).map(([id,a])=>({id,title:grant(id).name,owner:a.owner,start:a.start,end:['draft','review'].includes(a.status)?a.deadline:a.status==='submitted'?a.decisionDate:a.status==='received'?a.receivedDate:a.fundingDate||a.decisionDate,type:'application',progress:applicationProgress(a).value,funding:a.status==='awarded'?a.fundingDate:null})),...state.tasks.map(t=>({id:t.id,title:t.title,owner:t.owner,start:t.start,end:t.date,type:'task',progress:taskProgress(t)}))].filter(r=>r.end>=timelineStart&&r.start<=end);return heading('Your next steps')+todayTabs('timeline')+`<div class="month-heading"><div><h2>The work ahead</h2><p class="small muted">${dateLabel(timelineStart)} – ${dateLabel(end,{day:'numeric',month:'short',year:'numeric'})}</p></div><div class="controls"><button class="btn" data-action="timeline-prev" aria-label="Previous six weeks">‹</button><button class="btn" data-action="timeline-now">This period</button><button class="btn" data-action="timeline-next" aria-label="Next six weeks">›</button></div></div><p class="small muted">Open a bar to see its tasks or application. ◆ marks an expected funding date.</p><div class="gantt-scroll"><div class="gantt"><div class="gantt-head"><span>Work & owner</span><div class="gantt-weeks">${Array.from({length:6},(_,i)=>`<span>${dateLabel(plusDays(timelineStart,i*7))}</span>`).join('')}</div></div>${rows.map(r=>{const left=Math.max(0,daysBetween(timelineStart,r.start))/42*100;const right=Math.min(42,daysBetween(timelineStart,r.end)+1)/42*100;const funding=r.funding&&r.funding>=timelineStart&&r.funding<=end?Math.min(98,daysBetween(timelineStart,r.funding)/42*100):null;return `<div class="gantt-row"><a class="gantt-label" href="#${r.type==='task'?'tasks':'applications'}/${r.id}"><strong>${esc(r.title)}</strong><span>${esc(ownerName(r.owner))} · ${dateLabel(r.end)}</span></a><div class="gantt-track"><a href="#${r.type==='task'?'tasks':'applications'}/${r.id}" class="gantt-bar ${r.type}" style="left:${left}%;width:${Math.max(1.5,right-left)}%" aria-label="${esc(r.title)}, ${dateLabel(r.start)} to ${dateLabel(r.end)}, ${r.progress}%"><span style="width:${r.progress}%"></span><b>${r.progress}%</b></a>${funding!==null?`<a class="funding-diamond" href="#applications/${r.id}" style="left:${funding}%" aria-label="Expected funding for ${esc(r.title)} on ${dateLabel(r.funding)}">◆</a>`:''}</div></div>`}).join('')||'<div class="empty">No work scheduled in this period.</div>'}</div></div><p class="note">Application bars show preparation or follow-up windows. You can edit task dates and expected decision or funding dates in their details.</p>`}
function chatContext(){const r=route();if(r.startsWith('discussions')){const t=discussionById(r.split('/')[1])||discussionResults()[0];if(t)return {kind:'discussion',id:t.id,title:t.title,related:t.related};}if(r.startsWith('studio/')){const d=studioDoc();if(d)return {kind:'document',id:d.id,title:d.name,related:d.application||'',owner:'sarah',date:''};}if(r.startsWith('tasks/')){const t=state.tasks.find(t=>t.id===r.split('/')[1]);if(t)return {kind:'task',id:t.id,title:t.title,related:t.related,owner:t.owner,date:t.date};}if(r.startsWith('applications/')){const id=r.split('/')[1],a=state.applications[id];if(a)return {kind:'application',id,title:grant(id).name,related:id,owner:a.owner,date:a.followup||a.fundingDate||a.deadline};}if(r.startsWith('reports'))return {kind:'report',id:'report',title:'Welcoming Spaces',date:closeoutDue(),owner:'sarah',related:''};return {kind:'workspace',id:r,title:({today:'Today’s overview',calendar:'Your calendar',timeline:'Your timeline',readiness:'Grant readiness',tasks:'Team tasks',applications:'Your applications',opportunities:'Grant opportunities',library:'Your documents',plugins:'Your plugins',connections:'Your connections',settings:'Your profile',help:'Help & next steps'})[r]||'Your workspace',date:pacificDate(),owner:'sarah',related:''};}
function refreshChat(){const wasDocked=document.body.classList.contains('chat-open');const readingPosition=wasDocked?($('.shell')?.scrollTop||0):window.scrollY;const opening=chatOpen&&!$('#beedy-panel')?.classList.contains('is-open');syncBeedyDocument();document.body.classList.toggle('chat-open',chatOpen);document.body.classList.toggle('chat-expanded',chatOpen&&chatExpanded);$('#beedy-panel')?.remove();$('#app').insertAdjacentHTML('beforeend',chatPanel());document.querySelectorAll('.beedy-launch').forEach(b=>b.setAttribute('aria-expanded',String(chatOpen)));if(wasDocked!==chatOpen){if(chatOpen){$('.shell').scrollTop=readingPosition;}else{window.scrollTo({top:readingPosition,behavior:'instant'});}}if(opening)$('#beedy-panel')?.classList.add('is-entering');if(chatOpen){const log=$('.chat-messages');const latest=log.querySelector('.chat-message:last-of-type');log.scrollTop=agentBusy||agentError?log.scrollHeight:latest?.classList.contains('assistant')?Math.max(0,latest.offsetTop-12):state.chat.length?log.scrollHeight:0;}}
function recordSubmission(id){showDialog('<h2 id="dialog-title">Record your submission</h2>',`<p class="small muted">Use this after submitting through the funder’s portal. This updates your application record.</p><form id="submission-form" data-id="${id}"><label class="field">Submission date<input type="date" name="submitted" value="${pacificDate()}" max="${pacificDate()}" required></label><label class="field">Confirmation reference<input name="reference" placeholder="Optional reference from the funder" maxlength="100"></label><label class="field">Expected decision date<input name="decisionDate" type="date" value="${plusDays(pacificDate(),30)}" min="${pacificDate()}" required></label><label class="step-check"><input name="acknowledged" type="checkbox"><span>We have a submission receipt.</span></label><button class="btn primary">Save submission record</button></form>`)}
function recordDecision(id){showDialog('<h2 id="dialog-title">Record the funder’s decision</h2>',`<form id="decision-form" data-id="${id}"><label class="field">Outcome<select name="outcome" id="decision-outcome"><option value="awarded">Award confirmed</option><option value="declined">Not awarded</option></select></label><label class="field">Decision date<input name="date" type="date" value="${pacificDate()}" min="${state.applications[id].submitted}" max="${pacificDate()}" required></label><div id="award-fields"><label class="field">Award amount ($)<input name="amount" type="number" min="1" max="1000000" value="${state.applications[id].amount}" required></label><label class="field">Expected funding date<input name="fundingDate" type="date" min="${pacificDate()}" required></label></div><button class="btn primary">Save decision</button><p class="note">Record a confirmed decision, not a prediction.</p></form>`)}
function recordFunding(id){showDialog('<h2 id="dialog-title">Have the funds arrived?</h2>',`<p>${money(state.applications[id].amount)} · ${grant(id).name}</p><form id="funding-form" data-id="${id}"><label class="field">Date received<input type="date" name="receivedDate" value="${pacificDate()}" min="${state.applications[id].decisionDate}" max="${pacificDate()}" required></label><label class="step-check"><input type="checkbox" required><span>I have confirmed receipt of the full award.</span></label><button class="btn primary">Record receipt</button><p class="note">This records a status only. It does not move money.</p></form>`)}
function createAwardTasks(id,a){
 if(state.tasks.some(t=>t.related===id&&t.awardSetup))return;
 state.tasks.push({id:crypto.randomUUID(),title:'Set up the award budget',owner:'alex',start:pacificDate(),date:a.fundingDate,status:'todo',done:false,type:'task',related:id,awardSetup:true,notes:'Check the award agreement and confirm the expected payment date.',checks:[{name:'Review award conditions',done:false},{name:'Create the budget code',done:false}]},{id:crypto.randomUUID(),title:'Plan the funded programme kickoff',owner:'jordan',start:a.fundingDate,date:plusDays(a.fundingDate,7),status:'todo',done:false,type:'task',related:id,awardSetup:true,notes:'Coordinate delivery after the expected funding date. Confirm funds have arrived before committing costs.',checks:[{name:'Confirm delivery dates',done:false},{name:'Brief the programme team',done:false}]});
}
// Additional interactions are explicit user actions; Beedy never silently changes records.
document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b)return;const id=b.dataset.id;switch(b.dataset.action){case'chat-clear':clearBeedyChat();break;case'chat-undo-clear':undoClearBeedyChat();break;case'chat-expand':{const log=$('.chat-messages'),position=log?.scrollTop;chatExpanded=!chatExpanded;refreshChat();if(position!==undefined)$('.chat-messages').scrollTop=position;$('.chat-expand')?.focus({preventScroll:true});break;}case'chat-upload':$('#beedy-upload')?.click();break;case'chat-toggle':chatOpen=!chatOpen;refreshChat();if(chatOpen){checkAgentConnection();$('#beedy-message').focus()}break;case'chat-close':chatOpen=false;refreshChat();$('.beedy-launch')?.focus();break;case'chat-prompt':replyToBeedy(b.dataset.prompt);break;case'chat-create-task':{const m=state.chat.find(m=>m.id===id);if(!m?.suggestion)return;const t=m.suggestion;showDialog('<h2 id="dialog-title">Review Beedy’s suggested task</h2>',`<form id="new-team-task"><label class="field">Task name<input name="title" value="${esc(t.title)}" maxlength="120" required></label><label class="field">Assigned to${ownerSelect(t.owner)}</label><div class="money-inputs"><label class="field">Start date<input type="date" name="start" value="${pacificDate()}" required></label><label class="field">Due date<input name="date" type="date" value="${t.date}" min="${pacificDate()}" required></label></div><label class="field">Related application${relatedSelect(t.related)}</label><label class="field">Notes<textarea name="notes">${esc(t.notes)}</textarea></label><button class="btn primary">Create task</button></form>`);break;}case'application-filter':appFilter=id;render();break;case'record-submission':recordSubmission(id);break;case'record-decision':recordDecision(id);break;case'record-funding':recordFunding(id);break;case'timeline-prev':timelineStart=plusDays(timelineStart,-42);render();break;case'timeline-next':timelineStart=plusDays(timelineStart,42);render();break;case'timeline-now':timelineStart=weekStart();render();break;}});
document.addEventListener('change',e=>{if(e.target.id==='task-owner'){taskOwner=e.target.value;render()}if(e.target.id==='task-filter'){taskFilter=e.target.value;render()}if(e.target.id==='decision-outcome'){const hide=e.target.value==='declined';$('#award-fields').hidden=hide;$('#award-fields').querySelectorAll('input').forEach(i=>{i.disabled=hide;i.required=!hide})}});
document.addEventListener('input',e=>{if(e.target.id==='beedy-message'){chatDraft=e.target.value;e.target.style.height='auto';e.target.style.height=Math.min(140,e.target.scrollHeight)+'px';}if(e.target.name==='start'&&e.target.form?.elements.date)e.target.form.elements.date.min=e.target.value;});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&chatOpen&&!$('#detail').open){chatOpen=false;refreshChat();$('.beedy-launch')?.focus()}if(e.target.id==='beedy-message'&&e.key==='Enter'&&!e.shiftKey){e.preventDefault();if(chatDraft.trim())replyToBeedy(chatDraft.trim())}});
document.addEventListener('submit',e=>{const f=e.target,d=new FormData(f),id=f.dataset.id;let message='';
 if(f.id==='beedy-chat-form'){e.preventDefault();const q=String(d.get('message')).trim();if(q)replyToBeedy(q);return}
 if(f.id==='new-team-task'){const title=String(d.get('title')).trim();if(!title){toast('Give your task a name.');return}if(d.get('date')<d.get('start')){toast('The due date must be on or after the start date.');return}const task={id:crypto.randomUUID(),title,owner:String(d.get('owner')),start:String(d.get('start')),date:String(d.get('date')),related:String(d.get('related')),notes:String(d.get('notes')),status:'todo',done:false,type:'task',checks:[{name:'Complete the task',done:false}]};state.tasks.push(task);persist();closeDialog();go('tasks/'+task.id);toast('Task created and assigned');return}
 if(f.id==='task-edit-form'){const t=state.tasks.find(t=>t.id===id);if(d.get('date')<d.get('start')){toast('The due date must be on or after the start date.');return}let status=String(d.get('status'));let checks=t.checks.map((c,i)=>({...c,done:d.get('step-'+i)==='on'}));const extra=String(d.get('newstep')).trim();if(extra)checks.push({name:extra,done:false});if(e.submitter?.value==='complete'){status='done';checks=checks.map(c=>({...c,done:true}))}else if(status==='done'&&checks.some(c=>!c.done))status='doing';else if(checks.length&&checks.every(c=>c.done))status='done';else if(checks.some(c=>c.done))status='doing';Object.assign(t,{title:String(d.get('title')).trim()||t.title,owner:String(d.get('owner')),start:String(d.get('start')),date:String(d.get('date')),related:String(d.get('related')),notes:String(d.get('notes')),status,done:status==='done',checks});message='Task updated';}
 if(f.id==='working-application'){const a=state.applications[id];const checks=a.checks.map((c,i)=>({...c,done:d.get('prep-'+i)==='on'}));Object.assign(a,{title:String(d.get('title')),description:String(d.get('description')),amount:Number(d.get('amount')),owner:String(d.get('owner')),checks,status:checks.every(c=>c.done)&&e.submitter?.value==='review'?'review':'draft'});message=e.submitter?.value==='review'&&a.status!=='review'?'Progress saved. Complete all five steps before team review.':'Application progress saved';}
 if(f.id==='submission-form'){const a=state.applications[id];Object.assign(a,{status:'submitted',submitted:String(d.get('submitted')),reference:String(d.get('reference')),decisionDate:String(d.get('decisionDate')),acknowledged:d.get('acknowledged')==='on',followup:plusDays(String(d.get('submitted')),14)});a.history.push({label:'Submission recorded',date:a.submitted});message='Submission recorded. Nothing was sent.';closeDialog();}
 if(f.id==='tracking-form'){const a=state.applications[id];Object.assign(a,{owner:String(d.get('owner')),decisionDate:String(d.get('decisionDate')),followup:String(d.get('followup')),trackingNotes:String(d.get('trackingNotes')),acknowledged:a.status==='submitted'?d.get('acknowledged')==='on':a.acknowledged});if(d.get('fundingDate'))a.fundingDate=String(d.get('fundingDate'));message='Tracking details saved';}
 if(f.id==='decision-form'){const a=state.applications[id];a.status=String(d.get('outcome'));a.decisionDate=String(d.get('date'));a.acknowledged=true;if(a.status==='awarded'){a.amount=Number(d.get('amount'));a.fundingDate=String(d.get('fundingDate'));createAwardTasks(id,a);}a.history.push({label:a.status==='awarded'?'Award confirmed':'Not awarded; decision recorded',date:a.decisionDate});message='Decision recorded';closeDialog();}
 if(f.id==='funding-form'){const a=state.applications[id];a.status='received';a.receivedDate=String(d.get('receivedDate'));a.history.push({label:'Full award received',date:a.receivedDate});message='Funding receipt recorded';closeDialog();}
 if(message){persist();render();toast(message)}
});

// Live agent and dashboard insights are loaded after the core workspace definitions.
let agentConnection='checking',agentSignInMethod='demo',agentBusy=false,agentError='',insightSelected=null;
// Start a fresh conversation when moving away from the guided demo engine.
if(state.agentVersion!==3){state.chat=[];state.agentVersion=3;state.appliedChanges=[];persist();}
function isClearChatRequest(text){return /^(?:(?:can|could|would) you\s+)?(?:please\s+)?(?:clear|reset|delete)\s+(?:(?:all|this|the|my|current|our)\s+)*(?:chat(?:\s+(?:session|history|conversation))?|conversation)(?:\s+(?:please|now))?[.!?]*$/i.test(text.trim());}
function clearBeedyChat(){
 if(agentBusy){toast('Wait for Beedy to finish, then clear the chat.');return false;}
 if(!state.chat.length&&!chatDraft&&!agentError){toast('This chat is already empty.');return false;}
 const next={...state,chat:[],chatUndo:{messages:state.chat,draft:isClearChatRequest(chatDraft)?'':chatDraft,at:Date.now()}};
 if(!savePersonalState(next))return false;
 chatDraft='';agentError='';refreshChat();$('#beedy-message')?.focus();toast('Chat cleared. Your documents and work are unchanged.');return true;
}
function undoClearBeedyChat(){
 if(agentBusy||state.chat.length||!Array.isArray(state.chatUndo?.messages))return false;
 const backup=state.chatUndo,next={...state,chat:backup.messages};delete next.chatUndo;
 if(!savePersonalState(next))return false;
 chatDraft=backup.draft||'';agentError='';refreshChat();toast('Chat restored.');return true;
}
function syncBeedyDocument(){const d=selectContextDocument(route(),studioDocuments,pinnedDocumentId,excludedDocumentId);beedyDocument=documentContext(d);if(d)pinnedDocumentId=d.id;}
function currentPageContext(){return {...chatContext(),route:route(),attachedDocument:beedyDocument?{id:beedyDocument.id,name:beedyDocument.name}:null,documentTab:route().startsWith('studio/')?studioTab:null,selectedDate:route()==='calendar'?selectedDate:null,calendarMonth:route()==='calendar'?`${year}-${month+1}`:null,timelineStart:route()==='timeline'?timelineStart:null,taskFilters:route()==='tasks'?{status:taskFilter,owner:taskOwner}:null,applicationFilter:route()==='applications'?appFilter:null,discussionId:route().startsWith('discussions')?(discussionById(route().split('/')[1])||discussionResults()[0])?.id:null};}
function agentSnapshot(){syncBeedyDocument();const page=currentPageContext();return {documents:beedyDocument?[beedyDocument]:[],documentLibrary:studioDocuments.slice(0,100).map(d=>({id:d.id,name:d.name,words:wordCount(d.text),attached:d.id===beedyDocument?.id})),currentPage:page,organisationProfile,profile:{name:state.name,organisation:state.org,mission:state.mission||'',role:state.profileRole||'Programme lead'},plugins:{mode:'Workflow previews only; no mailbox access',preferences:state.connectionPlans||{}},discussions:discussionContextSnapshot(state.discussions||[],page.discussionId),demoDate:pacificDate(),currentDate:pacificDate(),timeZone:'America/Los_Angeles',organisation:state.org,tasks:state.tasks,applications:state.applications,opportunities:[...opportunities,...federal.context()],calendar:events(),readiness:state.readiness,report:state.report,team:members.map(m=>({id:m.id,name:m.name(),role:m.id==='sarah'?(state.profileRole||m.role):m.role}))};}
async function checkAgentConnection(){try{const r=await fetch('/api/beedy/status',{cache:'no-store'});if(!r.ok)throw new Error();const d=await r.json();agentConnection=connectionState(d);agentSignInMethod=d.signInMethod||'demo';document.querySelectorAll('[data-demo-signout]').forEach(b=>b.hidden=!(d.authenticated&&agentSignInMethod==='demo'));}catch{agentConnection='unavailable'}refreshChat();}
function chatMessage(m){
 const assistant=m.role==='assistant';
 return `<article class="chat-message ${assistant?'assistant':'user'}">${assistant?`<div class="answer-byline"><img src="assets/beedy-cutout.png" alt=""><span>Beedy</span>${m.elapsed?`<small>${m.elapsed}s</small>`:''}</div>`:''}<div class="answer-body">${assistant?(renderSavedGrantText(m.text)+renderGrantResults(m.grantResults)):`<p>${esc(m.text).replace(/\n/g,'<br>')}</p>`}</div>${(m.proposals||[]).map(p=>proposalCard(p,m.id)).join('')}${(m.grantActions||[]).map(a=>grantImportCard(a)).join('')}${(m.applicationActions||[]).map(a=>`<section class="grant-import-card"><h3>Draft your application</h3><p>${esc(a.title)}</p><p class="small muted">Use your nonprofit’s profile and project evidence to answer the funder’s questions.</p><button class="btn primary" data-action="chat-application-start" data-id="${esc(a.id)}">${a.grant?'Start draft':'Set up application'}</button></section>`).join('')}${m.insightDocumentId?`<a class="review-chat-link" href="#studio/${esc(m.insightDocumentId)}" data-action="grant-insights-open" data-id="${esc(m.insightDocumentId)}">Open saved grant analysis ${icon('arrow')}</a>`:''}${m.editDocumentId?`<a class="review-chat-link" href="#studio/${esc(m.editDocumentId)}" data-action="open-edit-review" data-id="${esc(m.editDocumentId)}"><span>${m.editCount} suggested edits<small>Compare wording and accept each change</small></span>${icon('arrow')}</a>`:''}${assistant?`<div class="answer-tools"><button class="iconbtn" data-action="answer-copy" data-id="${esc(m.id)}" aria-label="Copy answer" title="Copy answer">${icon('copy')}</button><button class="iconbtn" data-action="answer-download" data-id="${esc(m.id)}" aria-label="Download answer" title="Download answer">${icon('download')}</button>${m.documentName?`<span class="answer-source" title="${esc(m.documentName)}">${icon('file')}<span>${esc(m.documentName)}</span></span>`:''}</div>`:''}</article>`;
}
function chatPanel(){const c=chatContext();const disabled=agentBusy||agentConnection!=='ready';return `<aside id="beedy-panel" class="beedy-panel ${state.chat.length?'has-conversation':''} ${agentConnection==='signin'?'auth-required':''} ${chatOpen?'is-open':''}" aria-label="Beedy assistant" ${chatOpen?'':'inert'}>
 <header class="beedy-head"><div class="beedy-portrait"><img src="assets/beedy-cutout.png" alt="Beedy the kiwi"></div><div class="beedy-title"><h2>Beedy</h2><span>${agentConnection==='ready'?'Grants, documents, and team tasks':agentConnection==='signin'?'Sign in to start chatting':agentConnection==='checking'?'Checking connection…':agentConnection==='missing'?'Awaiting AI connection':'Connection unavailable'}</span></div><button class="iconbtn chat-expand" data-action="chat-expand" aria-label="${chatExpanded?'Narrow':'Expand'} Beedy" aria-pressed="${chatExpanded}" title="${chatExpanded?'Narrow':'Expand'} chat">${icon(chatExpanded?'contract':'expand')}</button><button class="iconbtn" data-action="chat-close" aria-label="Close Beedy">${icon('close')}</button></header>
 <div class="beedy-context">${icon('layers')}<span>Your workspace</span><span aria-hidden="true">/</span><strong>${esc(c.title)}</strong><button type="button" class="chat-clear" data-action="chat-clear" ${agentBusy||(!state.chat.length&&!chatDraft&&!agentError)?'disabled':''} title="${agentBusy?'Wait for Beedy to finish':'Clear this conversation; keep your documents and work'}">Clear chat</button></div>${state.chatUndo&&!state.chat.length?'<div class="chat-cleared" role="status"><span>Chat cleared</span><button type="button" data-action="chat-undo-clear">Undo</button></div>':''}
 <div class="chat-messages" role="log" aria-label="Conversation with Beedy">${!state.chat.length?`<div class="chat-welcome"><div class="welcome-orbit"><img src="assets/beedy-cutout.png" alt=""></div><h3>How can I help?</h3><p>Ask about a grant, review a document, or update a team task.</p></div>`:''}${state.chat.map(chatMessage).join('')}${agentBusy?'<div class="thinking" role="status"><i></i><i></i><i></i><span>Looking into it…</span></div>':''}${agentError?`<div class="agent-error" role="alert">${esc(agentError)}</div>`:''}</div>
 ${agentConnection==='signin'?`<div class="connection-note beedy-signin"><strong>Welcome to your workspace</strong><p>Sign in to continue. Your uploads and question stay in this browser.</p><a class="btn primary" data-action="beedy-signin" href="${esc(signInPath(route(),agentSignInMethod))}" target="_top">Sign in to Centring</a><button class="textlink" data-action="agent-recheck">Check sign-in status</button></div>`:''}${agentConnection==='unavailable'?'<div class="connection-note"><p>Couldn’t check your connection.</p><button class="textlink" data-action="agent-recheck">Try again</button></div>':''}${agentConnection==='missing'?'<div class="connection-note"><strong>Ready to connect</strong><p>Enable the secure AI connection to start a conversation.</p><button class="textlink" data-action="agent-recheck">Check connection</button></div>':''}
 <div class="chat-bottom"><div class="chat-suggestions"><button data-action="chat-prompt" data-prompt="Which deadlines need our attention this week?" ${disabled?'disabled':''}>Upcoming deadlines ${icon('arrow')}</button><button data-action="chat-prompt" data-prompt="Search live federal grants for our programme. Ask me for our focus area and nonprofit status if you need them." ${disabled?'disabled':''}>Find grants ${icon('arrow')}</button></div>
 <input type="file" id="beedy-upload" hidden accept=".pdf,.docx,.txt,.md,.png,.jpg,.jpeg" aria-label="Upload a document to Beedy"><form id="beedy-chat-form"><div class="chat-compose">${documentSelector()}<label class="sr-only" for="beedy-message">Message Beedy</label><textarea id="beedy-message" name="message" placeholder="Ask Beedy…" rows="1" maxlength="4000" required>${esc(chatDraft)}</textarea><div class="composer-controls"><button type="button" class="iconbtn" data-action="chat-upload" aria-label="Upload a document" title="Upload a document">${icon('upload')}</button><span>${beedyDocument?'Document + workspace':'Workspace context'}</span><button class="iconbtn send-message" type="submit" aria-label="Send message" ${disabled?'disabled':''}>${icon('send')}</button></div></div></form>
 <p class="chat-disclosure">${agentConnection==='ready'?'Check facts and sources before using AI suggestions.':agentConnection==='signin'?'Sign in to start chatting. Your files stay in your workspace.':'Your workspace is available while AI connects.'}</p></div></aside>`;}
function documentSelector(){return `<details class="chat-context-picker"><summary>${icon(beedyDocument?'file':'layers')}<span>${esc(beedyDocument?.name||'Add document context')}</span><small>${beedyDocument?(beedyDocument.truncated?'Partial source':'Attached'):''}</small>${icon('chevron')}</summary><div class="context-picker-body"><label class="beedy-document-select">Document for this conversation<select id="beedy-document-select" aria-label="Document for Beedy"><option value="">No document</option>${studioDocuments.map(d=>`<option value="${esc(d.id)}" ${beedyDocument?.id===d.id?'selected':''}>${esc(d.name)}</option>`).join('')}</select><small>Selected text is shared with AI when you send.</small></label>${beedyDocument?'<button type="button" class="textlink" data-action="document-detach">Remove document</button>':''}</div></details>`;}
function localTarget(change){return changeTarget(change,state)}
function proposalLabel(p){const c=p.change;const labels={task_create:'Create a task',task_update:'Update task',application_update:'Update application',readiness_update:'Update readiness'};return labels[c.kind]||'Suggested change';}
function patchLabel(key,value){const labels={owner:'Assigned to',start:'Start date',date:'Due date',deadline:'Application deadline',decisionDate:'Expected decision',fundingDate:'Expected funding',followup:'Follow-up date',trackingNotes:'Notes',related:'Related application',ready:'Ready',status:'Status',title:'Task',notes:'Notes'};return {label:labels[key]||key,value:key==='owner'?ownerName(value):key==='status'?taskStates[value]:key==='related'?(grant(value)?.name||'General team task'):key==='ready'?(value?'Yes':'No'):String(value)};}
function proposalCard(p,messageId){const target=localTarget(p.change),patch=p.change.patch;const title=patch.title||target?.title||(p.change.kind==='application_update'?grant(p.change.id)?.name:'')||proposalLabel(p);const details=Object.entries(patch).map(([key,value])=>{const label=patchLabel(key,value);return `<div><dt>${label.label}</dt><dd>${esc(label.value)}</dd></div>`}).join('');return `<div class="proposal-card"><div class="proposal-topline">${icon(p.applied?'check':'file')}<span>${p.applied?'Applied in your workspace':p.undone?'Change undone':proposalLabel(p)}</span><span class="proposal-state">${p.applied?'Done':p.undone?'Undone':'For review'}</span></div><h3>${esc(title)}</h3><p>${patch.owner?esc(ownerName(patch.owner))+' · ':''}${patch.date?'Due '+esc(dateLabel(patch.date,{day:'numeric',month:'short',year:'numeric'})):p.applied?'Updated in this workspace.':'Review the details before applying.'}</p><details class="proposal-details"><summary>View change details ${icon('chevron')}</summary><dl>${details}</dl></details>${p.applied?`<button class="textlink" data-action="agent-undo" data-message="${esc(messageId)}" data-id="${esc(p.id)}">Undo change</button>`:p.undone?'<span class="small muted">Ask Beedy for a fresh proposal.</span>':`<button class="btn primary" data-action="agent-apply" data-message="${esc(messageId)}" data-id="${esc(p.id)}">Apply change ${icon('arrow')}</button>`}</div>`;}
async function replyToBeedy(question,{insightDocumentId=null,insightGrantId=null,displayQuestion=question}={}){if(agentBusy||!question.trim())return;if(isClearChatRequest(question)){clearBeedyChat();return;}if(agentConnection!=='ready'){agentError=agentConnection==='signin'?'Use Sign in to Centring below. Your question hasn’t been sent.':agentConnection==='missing'?'Beedy is waiting for the secure AI connection. Your message hasn’t been sent.':'The AI connection is unavailable. Check the connection and try again.';chatDraft=question;refreshChat();return;}agentBusy=true;agentError='';const started=Date.now();const sourceName=beedyDocument?.name||'';const history=state.chat.slice(-12).map(m=>({role:m.role,content:m.text+(m.grantResults?.length?'\nDisplayed opportunities in order: ' + m.grantResults.map(g=>g.id+' '+g.name).join('\n'):'')}));state.chat.push({id:crypto.randomUUID(),role:'user',text:displayQuestion});chatDraft='';persist();if(route().startsWith('studio/')&&studioTab==='review')render();else refreshChat();try{if(beedyDocument){try{await ensureDocumentReview(beedyDocument.id);}catch{/* Reading still works when a file cannot support safe editing. */}}const requestWorkspace=agentSnapshot();const r=await fetch('/api/beedy/chat',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({message:question,projectId:studioDoc(beedyDocument?.id)?.applicationDraft?.projectId||undefined,history,workspace:requestWorkspace,context:chatContext().title}),signal:AbortSignal.timeout(120000)});const d=await r.json();if(!r.ok){if(d.code==='connection_required')agentConnection='missing';if(r.status===401||d.code==='sign_in_required')agentConnection='signin';throw new Error(d.error||'Beedy could not complete this request.')}if(d.source!=='openai'||typeof d.answer!=='string'||!Array.isArray(d.proposals))throw new Error('Beedy returned an unexpected response.');for(const p of d.proposals){validateChange(p.change,state);if(typeof p.id!=='string'||typeof p.before!=='string')throw new Error('Beedy returned an invalid change.');}let editDocumentId=null;const incoming=d.documentEdits||[];if(incoming.length){const docId=incoming[0].documentId;const source=requestWorkspace.documents.find(x=>x.id===docId);validateDocumentEdits({document_id:docId,edits:incoming.map(e=>({block_id:e.blockId,before:e.before,after:e.after,reason:e.reason}))},source);const doc=studioDoc(docId);if(!doc)throw new Error('The document is no longer available.');const next={...doc,review:{...doc.review,edits:[...doc.review.edits,...incoming]}};if(!await saveStudioDocument(next))throw new Error('The suggestions could not be saved. Try again.');editDocumentId=docId;}const applicationActions=(d.applicationActions||[]).slice(0,1);for(const a of applicationActions){if(!a||typeof a.id!=='string'||typeof a.title!=='string'||(a.documentId&&!requestWorkspace.documents.some(x=>x.id===a.documentId))||(a.grant&&(!/^\d{1,10}$/.test(a.grant.id)||a.grant.url!=='https://www.grants.gov/search-results-detail/'+a.grant.id)))throw new Error('Beedy returned an invalid application setup.');}const grantActions=(d.grantActions||[]).slice(0,2);for(const action of grantActions){if(!action?.grant||!/^\d{1,10}$/.test(action.grant.id)||action.grant.url!=='https://www.grants.gov/search-results-detail/'+action.grant.id)throw new Error('Beedy returned an invalid opportunity.');if(action.documentId&&!requestWorkspace.documents.some(x=>x.id===action.documentId))throw new Error('The linked document was not attached.');}let insightSaved=false;if(insightDocumentId){const target=studioDoc(insightDocumentId);if(!target||target.opportunity?.id!==insightGrantId)throw new Error('The linked opportunity changed. Run the analysis again.');insightSaved=await saveStudioDocument({...target,opportunityInsights:{text:d.answer,grantId:insightGrantId,createdAt:new Date().toISOString()}});if(!insightSaved)throw new Error('Could not save the grant analysis. Try again.');}state.chat.push({id:crypto.randomUUID(),role:'assistant',text:d.answer,grantResults:d.grantResults||[],grantActions,applicationActions,insightDocumentId:insightSaved?insightDocumentId:null,proposals:d.proposals,editDocumentId,editCount:incoming.length,elapsed:Math.max(1,Math.round((Date.now()-started)/1000)),documentName:sourceName});state.chat=state.chat.slice(-40);persist();}catch(error){agentError=error.name==='TimeoutError'?'Beedy took too long. Please try again.':error.message;chatDraft=question;}finally{agentBusy=false;if(route().startsWith('studio/')&&['review','insights'].includes(studioTab))render();else refreshChat();}}
function findProposal(button){return state.chat.find(m=>m.id===button.dataset.message)?.proposals?.find(p=>p.id===button.dataset.id)}
function applyAgentProposal(p){if(!p||p.applied||p.undone||(state.appliedChanges||[]).includes(p.id))return;try{validateChange(p.change,state);const current=localTarget(p.change);if(fingerprint(current)!==p.before)throw new Error('This record changed after Beedy’s suggestion. Ask for a fresh proposal.');p.undo=structuredClone(current);p.appliedId=applyChange(p.change,state,crypto.randomUUID());p.after=fingerprint(p.change.kind==='task_create'?state.tasks.find(t=>t.id===p.appliedId):localTarget(p.change));p.applied=true;state.appliedChanges=(state.appliedChanges||[]).concat(p.id).slice(-200);persist();render();toast('Change applied to your workspace');}catch(error){toast(error.message)}}
function undoAgentProposal(p){if(!p?.applied)return;const current=p.change.kind==='task_create'?state.tasks.find(t=>t.id===p.appliedId):localTarget(p.change);if(fingerprint(current)!==p.after){toast('This item has changed since then. Edit it directly to keep your newer work.');return;}if(p.change.kind==='task_create')state.tasks=state.tasks.filter(t=>t.id!==p.appliedId);else if(p.change.kind==='task_update'){const i=state.tasks.findIndex(t=>t.id===p.change.id);state.tasks[i]=p.undo;}else if(p.change.kind==='application_update')state.applications[p.change.id]=p.undo;else state.readiness[p.change.id]=p.undo;p.applied=false;p.undone=true;persist();render();toast('Change undone');}
function taskInsights(){const categories=[{id:'todo',name:'To do',color:'#dce7cf'},{id:'doing',name:'In progress',color:'#8ee53f'},{id:'done',name:'Complete',color:'#345732'}].map(c=>({...c,items:state.tasks.filter(t=>t.status===c.id)}));const total=state.tasks.length;let offset=0;const length=2*Math.PI*58;return `<section class="insight-panel task-insight"><div class="sectionhead"><div><h2>Task progress</h2><p>Task completion by status</p></div><a href="#tasks" aria-label="View all team tasks" class="iconbtn">${icon('arrow')}</a></div><div class="ring-layout"><div class="ring-wrap"><svg viewBox="0 0 160 160" aria-label="Task status chart"><circle cx="80" cy="80" r="58" fill="none" stroke="#f0f3ec" stroke-width="18"/>${categories.map(c=>{const fraction=total?c.items.length/total:0,start=offset;offset+=fraction*length;return c.items.length?`<circle class="ring-segment" cx="80" cy="80" r="58" fill="none" stroke="${c.color}" stroke-width="18" stroke-dasharray="${Math.max(0,fraction*length-5)} ${length}" stroke-dashoffset="${-start}" transform="rotate(-90 80 80)" tabindex="0" role="button" aria-label="${c.name}: ${c.items.length} tasks, ${Math.round(fraction*100)} percent. Open tasks." data-insight="${c.id}" data-action="insight-tasks" data-id="${c.id}"></circle>`:''}).join('')}</svg><div class="ring-centre" aria-hidden="true"><strong id="ring-value">${total}</strong><span id="ring-label">team tasks</span></div></div><div class="ring-legend">${categories.map(c=>`<button data-insight="${c.id}" data-action="insight-tasks" data-id="${c.id}"><i style="background:${c.color}"></i><span>${c.name}</span><b>${c.items.length}</b></button>`).join('')}<p id="ring-detail" aria-live="polite">Select a status to view its tasks.</p></div></div></section>`;}
function fundingInsights(){const groups=[{id:'active',label:'In preparation',note:'Requested · not awarded',color:'#dce7cf',items:Object.entries(state.applications).filter(([id,a])=>['draft','review'].includes(a.status))},{id:'waiting',label:'Awaiting a decision',note:'Requested · not awarded',color:'#8ee53f',items:Object.entries(state.applications).filter(([id,a])=>a.status==='submitted')},{id:'awards',label:'Confirmed awards',note:'Awarded · receipt tracked separately',color:'#345732',items:Object.entries(state.applications).filter(([id,a])=>['awarded','received'].includes(a.status))}].map(g=>({...g,total:g.items.reduce((sum,[id,a])=>sum+a.amount,0)}));const max=Math.max(1,...groups.map(g=>g.total));return `<section class="insight-panel funding-insight"><div class="sectionhead"><div><h2>Funding overview</h2><p>Application amounts by stage</p></div><a href="#applications" class="iconbtn" aria-label="View all applications">${icon('arrow')}</a></div><div class="funding-bars">${groups.map(g=>`<button class="funding-bar-button" data-action="insight-funding" data-id="${g.id}" aria-describedby="funding-tip-${g.id}"><span class="bar-heading"><span>${g.label}</span><strong>${money(g.total).replace('.00','')}</strong></span><span class="bar-track"><i style="width:${g.total/max*100}%;background:${g.color}"></i></span><span class="chart-tooltip" role="tooltip" id="funding-tip-${g.id}"><b>${g.items.length} ${g.items.length===1?'application':'applications'}</b>${g.items.map(([id,a])=>`<span>${grant(id).name} · ${money(a.amount).replace('.00','')}</span>`).join('')||'<span>No applications at this stage</span>'}<small>${g.note}</small></span></button>`).join('')}</div><p class="chart-footnote">Requested funding is separate from confirmed awards.</p></section>`;}
function overview(){const base=overviewV2().replace(currentDateHeading(),personalWelcome());const marker=todayTabs('today');return base.replace(marker,marker+studioLaunchCard()+`<div class="insights-grid">${taskInsights()}${fundingInsights()}</div>`);}
function highlightInsight(id){const category={todo:'To do',doing:'In progress',done:'Complete'}[id];const tasks=state.tasks.filter(t=>t.status===id);if(!$('#ring-value'))return;$('#ring-value').textContent=tasks.length;$('#ring-label').textContent=category;$('#ring-detail').textContent=`${state.tasks.length?Math.round(tasks.length/state.tasks.length*100):0}% of your team’s tasks. ${tasks.length?tasks.slice(0,2).map(t=>t.title).join(' · '):'Nothing here yet.'}`;document.querySelectorAll('.ring-segment').forEach(el=>el.classList.toggle('highlighted',el.dataset.insight===id));}
function resetInsight(){if(!$('#ring-value'))return;$('#ring-value').textContent=state.tasks.length;$('#ring-label').textContent='team tasks';$('#ring-detail').textContent='Hover for a closer look. Tap to open the tasks.';document.querySelectorAll('.ring-segment').forEach(el=>el.classList.remove('highlighted'));}
document.addEventListener('pointerover',e=>{const target=e.target.closest('[data-insight]');if(target)highlightInsight(target.dataset.insight)});
document.addEventListener('pointerout',e=>{if(e.target.closest('[data-insight]')&&!e.relatedTarget?.closest?.('[data-insight]'))resetInsight()});
document.addEventListener('focusin',e=>{const target=e.target.closest('[data-insight]');if(target)highlightInsight(target.dataset.insight)});
document.addEventListener('focusout',e=>{if(e.target.closest('[data-insight]'))resetInsight()});
document.addEventListener('keydown',e=>{if(e.target.matches('.ring-segment')&&['Enter',' '].includes(e.key)){e.preventDefault();taskFilter=e.target.dataset.id==='done'?'complete':e.target.dataset.id;taskOwner='all';go('tasks')}});
document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b)return;switch(b.dataset.action){case'agent-recheck':checkAgentConnection();break;case'agent-apply':applyAgentProposal(findProposal(b));break;case'agent-undo':undoAgentProposal(findProposal(b));break;case'insight-tasks':taskFilter=b.dataset.id==='done'?'complete':b.dataset.id;taskOwner='all';go('tasks');break;case'insight-funding':appFilter=b.dataset.id;go('applications');break;}});
