 blackbaud:{name:'Blackbaud',category:'Fundraising',description:'Bring your fundraising relationships into the picture.',workflow:'Review fundraising context',detail:'Plan which fundraising context your team would like beside its grant work. The exact available records will depend on your Blackbaud product and permissions.',field:'Product or team workspace',placeholder:'Raiser’s Edge NXT · Development team',preview:'People behind the support',message:'Keep useful relationship context close to the next application. Your team decides which records may be read.'},
 eventbrite:{name:'Eventbrite',category:'Events',description:'Keep community events close to your programme plans.',workflow:'Review event activity',detail:'Plan a view of selected events and attendance summaries to help your team prepare programme reports. Start with the organiser or event you care about.',field:'Organiser or event label',placeholder:'Open Studio Saturdays',preview:'From a gathering to a story',message:'Event details and attendance summaries could support your programme review. No attendee records are loaded in this preview.'},
