let dayPreviewAnchor=null,dayPreviewTimer;
function dayPreviewHTML(day){
 const list=events().filter(e=>e.date===day&&(route()!=='calendar'||filter==='all'||e.type===filter));
 const kinds={task:'Team task',report:'Report deadline',funding:'Funding',decision:'Decision / follow-up',opportunity:'Grant deadline'};
 return `<div class="day-preview-heading"><strong>${dateLabel(day,{weekday:'long',day:'numeric',month:'long'})}</strong><span>${list.length} ${list.length===1?'event':'events'}</span></div>${list.length?`<ul>${list.map(e=>`<li class="${e.done?'is-complete':''}"><span class="preview-dot">${e.done?'✓':''}</span><div><strong>${esc(e.title)}</strong><small>${esc(kinds[e.type]||'Event')}${e.owner?' · '+esc(ownerName(e.owner)):''} · ${e.done?'Completed':e.type==='task'?(taskStates[e.status]||'To do'):e.forecast?'Forecast':e.type==='decision'||e.type==='funding'?'Expected':'Scheduled'}</small></div></li>`).join('')}</ul>`:'<p class="day-preview-empty">No events scheduled for this day.</p>'}<div class="day-preview-hint">Select the day to open its agenda.</div>`;
}
function hideDayPreview(){clearTimeout(dayPreviewTimer);dayPreviewAnchor?.removeAttribute('aria-describedby');dayPreviewAnchor=null;document.querySelector('#calendar-day-preview')?.remove();}
function showDayPreview(anchor){
 if(dayPreviewAnchor===anchor){clearTimeout(dayPreviewTimer);return;}
 hideDayPreview();if(!anchor?.isConnected)return;
 dayPreviewAnchor=anchor;const panel=document.createElement('div');panel.id='calendar-day-preview';panel.className='calendar-day-preview';panel.setAttribute('role','tooltip');panel.innerHTML=dayPreviewHTML(anchor.dataset.date);document.body.append(panel);anchor.setAttribute('aria-describedby',panel.id);
 const rect=anchor.getBoundingClientRect(),width=panel.offsetWidth,height=panel.offsetHeight;
 panel.style.left=Math.max(12,Math.min(window.innerWidth-width-12,rect.left+rect.width/2-width/2))+'px';
 const below=rect.bottom+8;panel.style.top=Math.max(12,below+height<=window.innerHeight-12?below:rect.top-height-8)+'px';
}
function previewTarget(target){return target?.closest?.('.calday,.weekday');}
document.addEventListener('pointerover',e=>{if(e.pointerType==='touch')return;const anchor=previewTarget(e.target);if(anchor)showDayPreview(anchor);else if(e.target.closest?.('#calendar-day-preview'))clearTimeout(dayPreviewTimer);});
document.addEventListener('pointerout',e=>{if(previewTarget(e.target)||e.target.closest?.('#calendar-day-preview')){if(e.relatedTarget?.closest?.('#calendar-day-preview')||previewTarget(e.relatedTarget)===dayPreviewAnchor)return;clearTimeout(dayPreviewTimer);dayPreviewTimer=setTimeout(hideDayPreview,140);}});
document.addEventListener('focusin',e=>{const anchor=previewTarget(e.target);if(anchor&&anchor.matches(':focus-visible'))showDayPreview(anchor);});
document.addEventListener('focusout',e=>{if(previewTarget(e.target))hideDayPreview();});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&dayPreviewAnchor){e.stopImmediatePropagation();hideDayPreview();}},true);
window.addEventListener('resize',hideDayPreview);window.addEventListener('scroll',e=>{if(!e.target?.closest?.('#calendar-day-preview'))hideDayPreview();},true);
function startCalendarClock(){
 let previous=pacificDate();
 const tick=()=>{const now=pacificDate();if(now===previous)return;if(document.hidden||document.querySelector('#detail')?.open||document.activeElement?.matches('input,textarea,select,[contenteditable]'))return;
 if(selectedDate===previous){if(year===Number(previous.slice(0,4))&&month===Number(previous.slice(5,7))-1){year=Number(now.slice(0,4));month=Number(now.slice(5,7))-1;}selectedDate=now;}
 if(timelineStart===weekStart(previous))timelineStart=weekStart(now);previous=now;
 if(['today','calendar','timeline'].includes(route()))render();else refreshNotificationBell();};
 window.setInterval(tick,30000);window.addEventListener('focus',tick);document.addEventListener('visibilitychange',tick);
}


