 const doc={id:crypto.randomUUID(),name:(application.title||'Application').replace(/[\\/:*?"<>|\u0000-\u001f]/g,' ').slice(0,100)+' — application.docx',type:original.type,size:original.size,text,original,createdAt:now,updatedAt:now,extractionVersion:2,draft:{text:'',fields:{}},application:'',starred:true,applicationDraft:application,opportunity:application.grant||null,retrievedReferences:references,applicationTemplate:template?{id:template.id,name:template.name}:null,referenceSource:source?{id:source.id,name:source.name,text:source.text.slice(0,60000)}:null};
