async function draftFromOpportunity(grant,sourceId=''){
 if(applicationGenerating){toast('An application is already being prepared.');return;}
 if(!studioLoaded)await initStudio();
 const existing=studioDocuments.find(d=>d.applicationDraft&&d.opportunity?.id===grant.id);
 if(existing){closeDialog();openApplicationDraft(existing,true);return;}
 applicationGenerating=true;const controller=new AbortController(),dialog=$('#detail'),cancel=()=>controller.abort();
 const selected=studioDoc(sourceId),source=selected?.importedGrantId?studioDoc(selected.referenceSource?.id):selected?.applicationDraft?null:selected;
 showDialog('<h2 id="dialog-title">Preparing your application</h2>',`<div class="application-progress-dialog"><div class="application-context-heading"><strong>${esc(organisationProfile?.name||state.org)}</strong><span>${esc(grant.name)}</span></div><ol><li data-draft-step="find" class="current">Retrieve application materials</li><li data-draft-step="read">Read questions and requirements</li><li data-draft-step="write">Draft answers from your nonprofit profile</li><li data-draft-step="save">Save application in Documents</li></ol><p class="application-live-status" role="status">Checking the current official notice…</p><p class="small muted">Project budgets, partners, and commitments that aren’t in your records will be marked for review.</p><button class="btn" data-action="close-dialog">Cancel</button></div>`);
 dialog.addEventListener('close',cancel,{once:true});
 const status=(text,step)=>{const label=dialog.querySelector('[role="status"]');if(label)label.textContent=text;if(step)dialog.querySelectorAll('[data-draft-step]').forEach(el=>el.classList.toggle('current',el.dataset.draftStep===step));};
 try{
 if(!organisationProfile)await loadOrganisationProfile();
 if(controller.signal.aborted)throw new DOMException('Cancelled','AbortError');
 const response=await fetch('/api/grants/'+encodeURIComponent(grant.id)+'/materials',{signal:AbortSignal.any([controller.signal,AbortSignal.timeout(65000)])});const packet=await response.json();if(!response.ok)throw new Error(packet.error||'Could not retrieve the application materials.');
 status('Reading the funder’s application materials…','read');
 const material=await readOpportunityMaterials(packet,readDocumentFile,{signal:controller.signal,onProgress:text=>status(text,'read')});
 if(controller.signal.aborted)throw new DOMException('Cancelled','AbortError');
 status(material.retrievedSources.length?'Writing answers using your profile and the retrieved requirements…':'Writing a provisional draft; the full application questions were not publicly available…','write');
 const workspace=agentSnapshot();workspace.documents=source?[documentContext(source)]:[];
 const applicationRequest={projectId:pendingProjectId||undefined,grantId:grant.id,mission:organisationProfile?.mission||state.mission||'',programme:'',retrievedSources:material.retrievedSources,retrievalWarnings:material.retrievalWarnings};
 const r=await fetch('/api/beedy/chat',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({message:'Draft our application for this opportunity from our saved nonprofit profile and the retrieved funder requirements.',workspace,history:[],context:'Application drafting',applicationRequest}),signal:AbortSignal.any([controller.signal,AbortSignal.timeout(180000)])});const data=await r.json();if(!r.ok)throw new Error(data.error||'Beedy could not draft the application.');if(data.source!=='openai'||!data.application?.sections?.length)throw new Error('No complete application was returned.');
 if(controller.signal.aborted)throw new DOMException('Cancelled','AbortError');status('Saving your application…','save');
 const doc=await saveApplicationDraft(data.application,{source,references:material.sourceReferences});
 dialog.removeEventListener('close',cancel);closeDialog();openApplicationDraft(doc);
 }catch(error){
 if(controller.signal.aborted){toast('Application preparation cancelled.');return;}
 showDialog('<h2 id="dialog-title">Application not created</h2>',`<p role="alert">${esc(error.name==='TimeoutError'?'Reading the application took too long. Please try again.':error.message)}</p><p>Your saved documents are unchanged.</p>${proactiveHelp('draft')}<div class="dialog-actions"><button class="btn primary" data-action="opportunity-draft-retry">Try again</button><a class="btn" href="${esc(grant.url)}" target="_blank" rel="noopener noreferrer">Open official notice ↗</a></div>`);
 dialog.querySelector('[data-action="opportunity-draft-retry"]').addEventListener('click',()=>void draftFromOpportunity(grant,sourceId),{once:true});
 }finally{dialog.removeEventListener('close',cancel);applicationGenerating=false;}
}


