function updateCloudStatus(message){cloudMessage=message;document.querySelectorAll('.cloud-status').forEach(n=>{n.textContent=message;});}
async function initSharedStorage(){if(cloudInitPromise)return cloudInitPromise;cloudInitPromise=(async()=>{
 try{
  const original=localStorage.getItem('centring-lantern-local-v1');legacyWorkspace=original?JSON.parse(original):structuredClone(state);
  if(!original)localStorage.setItem('centring-lantern-local-v1',JSON.stringify(legacyWorkspace));
  sharedWorkspace=createSharedWorkspace({getState:()=>state,apply:data=>{state={...state,...data};localStorage.setItem('centring-lantern-workspace-v1',JSON.stringify(state));},status:updateCloudStatus});
  await sharedWorkspace.start();setInterval(()=>sharedWorkspace?.check(),20000);render();
 }catch(error){updateCloudStatus('Cloud unavailable; local copy kept');cloudInitPromise=null;throw error;}
})();return cloudInitPromise;}
