async function cloudSettings(){
 const docs=await localDocuments();const local=docs.filter(d=>!d._cloudOwner),pending=docs.filter(d=>d._cloudOwner===cloudAccount()&&d._cloudPending);
 showDialog('<h2 id="dialog-title">Shared workspace</h2>',`<p class="cloud-summary">${esc(cloudMessage)}</p><p>Everyone using this workspace sign-in can open the same saved documents, applications, tasks, and discussions. Your Beedy chat and personal photo stay on this device.</p><div class="cloud-actions"><button class="btn primary" data-action="cloud-refresh">Sync and refresh</button><button class="btn" data-action="cloud-export">Download backup</button></div><h3>Work saved on this device</h3><p>${local.length} documents are waiting to be uploaded. Importing keeps existing shared records and adds missing records from this device.</p><button class="btn" data-action="cloud-import">Upload this device’s work</button>${pending.length?`<h3>${pending.length} documents need syncing</h3><p>If someone has edited the same document, save your local edits as separate copies to keep both versions.</p><button class="btn" data-action="cloud-recover">Save local edits as copies</button>`:''}${sharedWorkspace?.conflicts.length?`<h3>Conflicting workspace changes</h3><p>${esc(sharedWorkspace.conflicts.join(', '))}</p><p>Download a backup first, then load the team’s version. Your backup retains your local changes for comparison.</p><button class="btn" data-action="cloud-use-team">Back up my changes and load team version</button>`:''}<p class="small muted">Earlier saved file versions are retained for recovery. This is a shared sign-in workspace; individual member accounts and permissions are not configured yet.</p>`);
}
async function exportCloudBackup(){
 const encode=async value=>{if(value instanceof Blob){const bytes=new Uint8Array(await value.arrayBuffer());let binary='';for(let i=0;i<bytes.length;i+=16384)binary+=String.fromCharCode(...bytes.subarray(i,i+16384));return {fileBase64:btoa(binary),type:value.type};}if(Array.isArray(value))return Promise.all(value.map(encode));if(value&&typeof value==='object'){const out={};for(const [k,v]of Object.entries(value))out[k]=await encode(v);return out;}return value;};
 const backup=await encode({format:'centring-backup-v1',exportedAt:new Date().toISOString(),workspace:state,legacyWorkspace,documents:(await localDocuments()).filter(d=>!d._cloudOwner||d._cloudOwner===cloudAccount())});download('Centring-workspace-backup.json',JSON.stringify(backup),'application/json');
}
document.addEventListener('click',async e=>{const action=e.target.closest('[data-action]')?.dataset.action;if(!action?.startsWith('cloud-'))return;const button=e.target.closest('button');if(button)button.disabled=true;try{
 if(action==='cloud-settings'){await cloudSettings();return;}
 if(action==='cloud-export'){await exportCloudBackup();return;}
 if(!sharedWorkspace?.ready)await initSharedStorage();
 if(action==='cloud-import'){await migrateLocalDocuments();state={...state,...importMissing(sharedPart(state),sharedPart(legacyWorkspace||{}))};persist();await sharedWorkspace.flush();}
 if(action==='cloud-recover')await saveConflictedDocumentsAsCopies();
 if(action==='cloud-use-team'){await exportCloudBackup();await sharedWorkspace.useCloud();}
 if(action==='cloud-refresh'){await retryLocalDocuments();await sharedWorkspace.refresh();}
 studioDocuments=await allDocuments();closeDialog();render();toast(cloudMessage);
 }catch(error){toast(error.message);}finally{if(button)button.disabled=false;}});
